# ruff: noqa: E501
"""Append-only definition items with owner-maintained exact current identities.

Frozen 0752 predecessors; all runtime writes remain receipt-bound.
"""

PREDECESSOR_PROTECT_FIXED_DEFINITION = "CREATE OR REPLACE FUNCTION public.protect_fixed_definition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n BEGIN\n IF TG_TABLE_NAME='definition_revisions' AND TG_OP='UPDATE' AND current_user='pdos_next_owner'\n  AND OLD.status='draft' AND NOT OLD.sealed AND NEW.status='published' AND NEW.sealed\n  AND (to_jsonb(NEW)-ARRAY['status','sealed','publication_receipt_id']) IS NOT DISTINCT FROM\n      (to_jsonb(OLD)-ARRAY['status','sealed','publication_receipt_id']) THEN RETURN NEW; END IF;\n IF TG_OP='UPDATE' AND TG_TABLE_NAME='definition_revisions'\n AND (to_jsonb(OLD)->>'sealed')='false' AND (to_jsonb(NEW)->>'sealed')='true'\n AND (to_jsonb(NEW)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n   =(to_jsonb(OLD)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n AND m3_result_access(NEW.tenant_id,NEW.category_id,'definition_revisions',NEW.id)\n THEN RETURN NEW; END IF;\n RAISE EXCEPTION 'definition snapshots are immutable'; END $function$\n"

PREDECESSOR_M3_G0_DERIVATION_ASSERT = "CREATE OR REPLACE FUNCTION public.m3_g0_derivation_assert(t uuid, c uuid, did uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE decision proposal_decisions; proposal proposals; submission proposal_submissions; definition definition_revisions;\n model products; variant product_variants; variant_version variant_revisions; project projects; receipt action_receipts;\n rx xid; spec_item jsonb; expected_spec definition_specs; actual_spec definition_specs; spec_count bigint;\n expected_claims jsonb; frozen_claims jsonb; baseline_claim jsonb;\nBEGIN\n SELECT * INTO STRICT decision FROM proposal_decisions WHERE tenant_id=t AND category_id=c AND id=did;\n IF decision.outcome<>'approved' THEN RETURN; END IF;\n SELECT * INTO STRICT proposal FROM proposals WHERE tenant_id=t AND category_id=c AND id=decision.proposal_id;\n SELECT * INTO STRICT submission FROM proposal_submissions WHERE tenant_id=t AND category_id=c AND id=decision.submission_id;\n SELECT * INTO STRICT receipt FROM action_receipts WHERE tenant_id=t AND category_id=c AND id=decision.receipt_id;\n SELECT * INTO STRICT definition FROM definition_revisions WHERE tenant_id=t AND category_id=c AND id=decision.created_definition_id;\n SELECT * INTO STRICT model FROM products WHERE tenant_id=t AND category_id=c AND id=decision.created_product_id FOR UPDATE;\n SELECT * INTO STRICT project FROM projects WHERE tenant_id=t AND category_id=c AND id=decision.created_project_id;\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=t AND id=receipt.id;\n IF receipt.operation IS DISTINCT FROM 'proposal.g0.decide' OR receipt.subject_type IS DISTINCT FROM 'proposal'\n  OR receipt.subject_id IS DISTINCT FROM proposal.id OR receipt.actor_id IS DISTINCT FROM decision.decided_by\n  OR receipt.subject_revision IS DISTINCT FROM proposal.revision\n  OR receipt.requester_id IS DISTINCT FROM decision.decided_by OR receipt.actor_id IS DISTINCT FROM scope_actor()\n  OR scope_actor() IS DISTINCT FROM scope_requester() OR category_access(t,c) IS DISTINCT FROM true\n  OR NOT EXISTS(SELECT 1 FROM grants grant_row JOIN principals signer ON signer.tenant_id=grant_row.tenant_id AND signer.id=grant_row.principal_id\n   WHERE grant_row.tenant_id=t AND grant_row.category_id=c AND grant_row.principal_id=decision.decided_by\n    AND grant_row.product_manager AND (grant_row.expires_at IS NULL OR grant_row.expires_at>statement_timestamp())\n    AND signer.active AND signer.kind='human')\n  OR receipt.agent_run_id IS NOT NULL OR receipt.run_id IS NOT NULL OR receipt.product_id IS NOT NULL\n  OR submission.proposal_id IS DISTINCT FROM proposal.id OR submission.reviewer_id IS DISTINCT FROM decision.decided_by\n  OR proposal.current_submission_id IS DISTINCT FROM submission.id OR decision.review_digest IS DISTINCT FROM submission.document_digest\n  OR definition.product_id IS DISTINCT FROM model.id OR definition.g0_decision_id IS DISTINCT FROM decision.id\n  OR definition.variant_id IS DISTINCT FROM decision.created_variant_id OR definition.revision<>1 OR NOT definition.sealed OR definition.status<>'draft'\n  OR definition.source_proposal_id IS DISTINCT FROM proposal.id OR definition.source_submission_id IS DISTINCT FROM submission.id\n  OR definition.source_proposal_revision IS DISTINCT FROM submission.revision OR definition.owner_id IS DISTINCT FROM proposal.owner_id\n  OR definition.visibility IS DISTINCT FROM proposal.effective_visibility\n  OR project.product_id IS DISTINCT FROM model.id OR project.g0_decision_id IS DISTINCT FROM decision.id OR project.owner_id IS DISTINCT FROM decision.project_owner_id\n  OR project.visibility IS DISTINCT FROM proposal.effective_visibility\n  OR rx::text::bigint IS DISTINCT FROM txid_current()%4294967296\n  OR rx IS DISTINCT FROM (SELECT xmin FROM proposal_decisions WHERE tenant_id=t AND id=decision.id)\n  OR rx IS DISTINCT FROM (SELECT xmin FROM proposals WHERE tenant_id=t AND id=proposal.id)\n  OR rx IS DISTINCT FROM (SELECT xmin FROM definition_revisions WHERE tenant_id=t AND id=definition.id)\n  OR rx IS DISTINCT FROM (SELECT xmin FROM projects WHERE tenant_id=t AND id=project.id)\n  OR receipt.result->>'decision_id' IS DISTINCT FROM decision.id::text OR receipt.result->>'product_id' IS DISTINCT FROM model.id::text\n  OR receipt.result->>'definition_id' IS DISTINCT FROM definition.id::text OR receipt.result->>'project_id' IS DISTINCT FROM project.id::text\n  OR NOT EXISTS(SELECT 1 FROM project_product_links link WHERE link.tenant_id=t AND link.category_id=c AND link.project_id=project.id\n   AND link.product_id=model.id AND link.definition_id=definition.id AND link.definition_revision=definition.revision\n   AND link.variant_id IS NOT DISTINCT FROM definition.variant_id AND link.xmin=rx) THEN\n  RAISE EXCEPTION 'G0 derivation outputs require exact same transaction named receipt' USING ERRCODE='23514'; END IF;\n IF proposal.entry_kind='derivative' OR proposal.target_kind='new_variant' THEN\n  IF m3_published_baseline_valid(t,c,proposal.baseline_product_id,proposal.baseline_definition_id,proposal.baseline_definition_revision) IS DISTINCT FROM true\n   OR definition.derived_from_definition_id IS DISTINCT FROM proposal.baseline_definition_id\n   OR definition.derived_from_definition_revision IS DISTINCT FROM proposal.baseline_definition_revision\n   OR submission.frozen_document->>'baseline_product_id' IS DISTINCT FROM proposal.baseline_product_id::text\n   OR submission.frozen_document->>'baseline_definition_id' IS DISTINCT FROM proposal.baseline_definition_id::text\n   OR (submission.frozen_document->>'baseline_definition_revision')::integer IS DISTINCT FROM proposal.baseline_definition_revision\n   OR NOT EXISTS(SELECT 1 FROM definition_revisions baseline JOIN products parent ON parent.tenant_id=baseline.tenant_id AND parent.id=baseline.product_id\n    WHERE baseline.tenant_id=t AND baseline.category_id=c AND baseline.id=proposal.baseline_definition_id\n     AND source_object_audience(t,c,'definition_revisions',baseline.id,baseline.owner_id,baseline.visibility)\n     AND source_object_audience(t,c,'products',parent.id,parent.owner_id,parent.visibility)\n     AND (proposal.effective_visibility='private' OR (baseline.visibility='category' AND parent.visibility='category' AND m3_definition_root_private(t,c,baseline.id,proposal.baseline_definition_revision) IS FALSE))) THEN\n   RAISE EXCEPTION 'G0 derivation baseline must be actual readable fixed publication' USING ERRCODE='23514'; END IF;\n  -- The dependency set comes from persisted source edges, not a caller's\n  -- declaration. The frozen document and actual signed consumption must both\n  -- contain the complete recursive Claim closure of the fixed parent.\n  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)\n   ORDER BY jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)),'[]') INTO expected_claims\n   FROM jsonb_array_elements(m3_baseline_reference_graph(t,c,proposal.baseline_definition_id,proposal.baseline_definition_revision)) ref\n   WHERE ref->>'type'='claim';\n  IF jsonb_typeof(coalesce(submission.frozen_document->'baseline_claim_refs','[]')) IS DISTINCT FROM 'array' THEN\n   RAISE EXCEPTION 'G0 baseline claim closure differs from fixed publication' USING ERRCODE='23514'; END IF;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(submission.frozen_document->'baseline_claim_refs','[]')) ref\n   WHERE ref->>'type' IS DISTINCT FROM 'claim' OR ref->>'id' IS NULL OR ref->>'version' IS NULL) THEN\n   RAISE EXCEPTION 'G0 baseline claim closure differs from fixed publication' USING ERRCODE='23514'; END IF;\n  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)\n   ORDER BY jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)),'[]') INTO frozen_claims\n   FROM jsonb_array_elements(coalesce(submission.frozen_document->'baseline_claim_refs','[]')) ref;\n  IF frozen_claims IS DISTINCT FROM expected_claims THEN\n   RAISE EXCEPTION 'G0 baseline claim closure differs from fixed publication' USING ERRCODE='23514'; END IF;\n  FOR baseline_claim IN SELECT ref FROM jsonb_array_elements(expected_claims) ref LOOP\n   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(submission.frozen_document->'source_refs','[]')) ref\n    WHERE ref->>'type'='claim' AND (ref->>'id')::uuid=(baseline_claim->>'id')::uuid\n     AND (ref->>'version')::integer=(baseline_claim->>'version')::integer)\n    OR (SELECT count(*) FROM claim_consumptions consumption\n     WHERE consumption.tenant_id=t AND consumption.category_id=c AND consumption.product_id=model.id\n      AND consumption.claim_id=(baseline_claim->>'id')::uuid AND consumption.claim_version=(baseline_claim->>'version')::integer\n      AND consumption.decision_id=decision.id AND consumption.definition_id=definition.id\n      AND consumption.receipt_id=receipt.id AND consumption.consumer_id=decision.id AND consumption.xmin=rx)<>1 THEN\n    RAISE EXCEPTION 'G0 baseline claim consumption must commit with decision' USING ERRCODE='23514'; END IF;\n  END LOOP;\n ELSE\n  IF definition.derived_from_definition_id IS NOT NULL OR definition.derived_from_definition_revision IS NOT NULL\n   OR proposal.baseline_product_id IS NOT NULL OR proposal.baseline_definition_id IS NOT NULL OR proposal.baseline_definition_revision IS NOT NULL THEN\n   RAISE EXCEPTION 'new product has no derivation baseline' USING ERRCODE='23514'; END IF;\n END IF;\n IF proposal.target_kind='new_variant' THEN\n  IF (SELECT count(*) FROM product_variants actual_variant\n   JOIN variant_revisions actual_version ON actual_version.tenant_id=actual_variant.tenant_id\n    AND actual_version.category_id=actual_variant.category_id AND actual_version.variant_id=actual_variant.id\n   WHERE actual_variant.tenant_id=t AND actual_variant.category_id=c AND actual_variant.id=decision.created_variant_id\n    AND actual_variant.product_id=model.id AND actual_variant.g0_decision_id=decision.id AND actual_variant.xmin=rx\n    AND actual_version.product_id=model.id AND actual_version.definition_id=definition.id\n    AND actual_version.revision=1 AND actual_version.xmin=rx\n    AND actual_version.parent_definition_id=proposal.baseline_definition_id\n    AND actual_version.parent_revision=proposal.baseline_definition_revision\n    AND actual_version.effective_definition=jsonb_build_object('definition_id',definition.id,'definition_revision',definition.revision))<>1 THEN\n   RAISE EXCEPTION 'G0 variant canonical definition mismatch' USING ERRCODE='23514'; END IF;\n  SELECT * INTO variant FROM product_variants WHERE tenant_id=t AND category_id=c AND id=decision.created_variant_id;\n  SELECT * INTO variant_version FROM variant_revisions WHERE tenant_id=t AND category_id=c AND variant_id=variant.id AND revision=1;\n  IF variant.id IS NULL OR variant_version.id IS NULL OR model.id IS DISTINCT FROM proposal.baseline_product_id OR variant.product_id IS DISTINCT FROM model.id\n   OR variant.g0_decision_id IS DISTINCT FROM decision.id OR variant.owner_id IS DISTINCT FROM proposal.owner_id\n   OR variant.visibility IS DISTINCT FROM proposal.effective_visibility OR variant_version.visibility IS DISTINCT FROM proposal.effective_visibility\n   OR variant_version.definition_id IS DISTINCT FROM definition.id OR variant_version.product_id IS DISTINCT FROM model.id\n   OR variant_version.owner_id IS DISTINCT FROM proposal.owner_id OR variant_version.parent_definition_id IS DISTINCT FROM proposal.baseline_definition_id\n   OR variant_version.parent_revision IS DISTINCT FROM proposal.baseline_definition_revision\n   OR variant_version.previous_revision_id IS NOT NULL\n   OR variant_version.sources IS DISTINCT FROM jsonb_build_array(jsonb_build_object('type','definition','id',proposal.baseline_definition_id,'version',proposal.baseline_definition_revision))\n   OR variant_version.effective_definition IS DISTINCT FROM jsonb_build_object('definition_id',definition.id,'definition_revision',definition.revision)\n   OR rx IS DISTINCT FROM (SELECT xmin FROM product_variants WHERE tenant_id=t AND id=variant.id)\n   OR rx IS DISTINCT FROM (SELECT xmin FROM variant_revisions WHERE tenant_id=t AND id=variant_version.id)\n   OR receipt.result->>'variant_id' IS DISTINCT FROM variant.id::text THEN\n   RAISE EXCEPTION 'G0 variant canonical definition mismatch' USING ERRCODE='23514'; END IF;\n ELSIF proposal.target_kind='new_product' THEN\n  IF decision.created_variant_id IS NOT NULL OR definition.variant_id IS NOT NULL\n   OR rx IS DISTINCT FROM (SELECT xmin FROM products WHERE tenant_id=t AND id=model.id) OR model.visibility IS DISTINCT FROM proposal.effective_visibility\n   OR model.parent_product_id IS DISTINCT FROM (CASE WHEN proposal.entry_kind='derivative' THEN proposal.baseline_product_id ELSE NULL END)\n   OR (proposal.baseline_product_id IS NOT NULL AND model.id=proposal.baseline_product_id) THEN\n   RAISE EXCEPTION 'G0 new product identity or derivation mismatch' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'unknown G0 target scope' USING ERRCODE='23514'; END IF;\n -- Canonical specification facts are exactly the fixed submitted items,\n -- including human-value and AI provenance fields; JSON numeric strings are\n -- coerced through the actual row type before comparison.\n SELECT count(*) INTO spec_count FROM jsonb_array_elements(submission.frozen_document->'items') item WHERE item->>'kind'='spec';\n IF spec_count<>(SELECT count(*) FROM definition_specs spec WHERE spec.tenant_id=t AND spec.definition_id=definition.id) THEN\n  RAISE EXCEPTION 'G0 canonical specification set differs from submission' USING ERRCODE='23514'; END IF;\n FOR spec_item IN SELECT item FROM jsonb_array_elements(submission.frozen_document->'items') item WHERE item->>'kind'='spec' LOOP\n  SELECT * INTO STRICT actual_spec FROM definition_specs WHERE tenant_id=t AND category_id=c AND definition_id=definition.id AND key=spec_item->'content'->>'key';\n  SELECT * INTO expected_spec FROM jsonb_populate_record(NULL::definition_specs,(spec_item->'content')||jsonb_build_object(\n   'text',spec_item->'content'->'text_value','method',spec_item->'content'->'verification_method','state','proposed',\n   'test_conditions',coalesce(spec_item->'content'->'test_conditions','[]'::jsonb),\n   'reason',coalesce(spec_item->'content'->>'reason',''),'source_refs',spec_item->'source_refs','origin',spec_item->>'origin',\n   'writer_id',spec_item->'writer_id','run_id',spec_item->'run_id','confirmed_by',spec_item->'confirmed_by','receipt_id',receipt.id));\n  IF (to_jsonb(actual_spec)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at']) IS DISTINCT FROM\n     (to_jsonb(expected_spec)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at']) THEN\n   RAISE EXCEPTION 'G0 canonical specification differs from frozen human value or provenance' USING ERRCODE='23514'; END IF;\n END LOOP;\n -- The deferred atom sees the complete persisted canonical graph, after the\n -- INSERT RETURNING statement-snapshot window has closed.\n IF definition_sources_visible(t,c,model.id,definition.id) IS DISTINCT FROM true THEN\n  RAISE EXCEPTION 'G0 canonical definition sources are not currently readable' USING ERRCODE='23514'; END IF;\nEND $function$\n"

PREDECESSOR_M3_REFERENCE_GRAPH = "CREATE OR REPLACE FUNCTION public.m3_reference_graph(t uuid, c uuid, seeds jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE queue jsonb;\n refs jsonb='[]'; cursor_index integer=0; node jsonb; ref jsonb; path jsonb; token text; children jsonb;\nBEGIN\n IF jsonb_typeof(seeds) IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;\n SELECT coalesce(jsonb_agg(jsonb_build_object('ref',seed,'path','[]'::jsonb)),'[]')\n  INTO queue FROM jsonb_array_elements(seeds) seed;\n WHILE cursor_index<jsonb_array_length(queue) LOOP\n  node=queue->cursor_index; cursor_index=cursor_index+1; ref=node->'ref'; path=node->'path';\n  IF jsonb_typeof(ref) IS DISTINCT FROM 'object'\n   OR coalesce(ref->>'type','')<>ALL(ARRAY['artifact','original','snapshot','claim','knowledge','definition','parameter','human'])\n   OR jsonb_typeof(ref->'id') IS DISTINCT FROM 'string'\n   OR jsonb_typeof(ref->'version') IS DISTINCT FROM 'number'\n   OR (ref->>'version')::integer<1 THEN RETURN NULL; END IF;\n  token=(ref->>'type')||':'||(ref->>'id')||':'||(ref->>'version');\n  IF token IS NULL OR path ? token THEN RETURN NULL; END IF;\n  refs=refs||jsonb_build_array(ref); path=path||jsonb_build_array(token); children='[]';\n  IF ref->>'type'='definition' THEN\n   IF NOT EXISTS(SELECT 1 FROM definition_revisions d WHERE d.tenant_id=t AND d.category_id=c\n    AND d.id=(ref->>'id')::uuid AND d.revision=(ref->>'version')::integer) THEN RETURN NULL; END IF;\n   SELECT coalesce(jsonb_agg(source),'[]') INTO children FROM (\n    SELECT jsonb_build_object('type','artifact','id',s.artifact_id,'version',s.source_revision,'line',s.line,'quote',s.quote) source\n     FROM definition_sources s WHERE s.tenant_id=t AND s.category_id=c AND s.definition_id=(ref->>'id')::uuid\n    UNION ALL SELECT item FROM definition_specs spec CROSS JOIN LATERAL jsonb_array_elements(spec.source_refs) item\n     WHERE spec.tenant_id=t AND spec.category_id=c AND spec.definition_id=(ref->>'id')::uuid\n    UNION ALL SELECT jsonb_build_object('type','definition','id',d.derived_from_definition_id,'version',d.derived_from_definition_revision)\n     FROM definition_revisions d WHERE d.tenant_id=t AND d.category_id=c AND d.id=(ref->>'id')::uuid AND d.derived_from_definition_id IS NOT NULL\n    UNION ALL SELECT jsonb_build_object('type','definition','id',parent.id,'version',parent.revision)\n     FROM definition_revisions d JOIN definition_revisions parent ON parent.tenant_id=d.tenant_id AND parent.category_id=d.category_id AND parent.id=d.parent_definition_id\n     WHERE d.tenant_id=t AND d.category_id=c AND d.id=(ref->>'id')::uuid\n   ) edges;\n  ELSIF ref->>'type'='knowledge' THEN\n   IF NOT EXISTS(SELECT 1 FROM category_knowledge_entries knowledge\n    WHERE knowledge.tenant_id=t AND knowledge.category_id=c AND knowledge.id=(ref->>'id')::uuid\n     AND knowledge.version=(ref->>'version')::integer) THEN RETURN NULL; END IF;\n   -- Mirror category_service._references, never arbitrary nested dictionaries.\n   SELECT coalesce(jsonb_agg(edge),'[]') INTO children FROM category_knowledge_entries knowledge\n    CROSS JOIN LATERAL (\n     SELECT item AS edge FROM jsonb_array_elements(knowledge.source_refs) item\n     UNION ALL SELECT item FROM jsonb_array_elements(CASE WHEN knowledge.kind='voice'\n      THEN coalesce(knowledge.content->'representative_refs','[]') ELSE '[]'::jsonb END) item\n     UNION ALL SELECT item->'source_ref' FROM jsonb_array_elements(CASE WHEN knowledge.kind='competitor'\n      THEN coalesce(knowledge.content->'metrics','[]') || coalesce(knowledge.content->'features','[]')\n       || coalesce(knowledge.content->'prices','[]') ELSE '[]'::jsonb END) item\n      WHERE item->'source_ref' IS NOT NULL AND item->'source_ref'<>'null'::jsonb\n    ) registered\n    WHERE knowledge.tenant_id=t AND knowledge.category_id=c AND knowledge.id=(ref->>'id')::uuid\n     AND knowledge.version=(ref->>'version')::integer;\n  ELSIF ref->>'type'='claim' THEN\n   SELECT coalesce(jsonb_agg(jsonb_build_object('type',claim.source_kind,'id',coalesce(claim.artifact_id,claim.snapshot_id),\n    'version',claim.source_revision,'line',claim.line,'quote',claim.quote)),'[]') INTO children\n    FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=(ref->>'id')::uuid;\n  END IF;\n  SELECT queue||coalesce(jsonb_agg(jsonb_build_object('ref',child,'path',path)),'[]') INTO queue FROM jsonb_array_elements(children) child;\n END LOOP;\n RETURN (SELECT coalesce(jsonb_agg(DISTINCT item ORDER BY item),'[]') FROM jsonb_array_elements(refs) item);\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;\nEND $function$\n"

PREDECESSOR_M3_EVIDENCE_LINK_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_link_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; actual_link_run agent_runs; p proposals; i proposal_items; k category_knowledge_entries;\n target_link_spec definition_specs; def definition_revisions; root jsonb; shared boolean; target_product uuid; target_proposal uuid;\nBEGIN\n IF TG_OP='UPDATE' THEN\n  SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.reverted_by_receipt_id;\n  IF r.category_id<>NEW.category_id OR r.actor_id<>r.requester_id OR r.actor_id IS DISTINCT FROM scope_actor()\n   OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n   OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n      (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id)\n   OR NOT ( (r.operation='evidence.claim.withdraw' AND NEW.evidence_type='claim' AND r.subject_id=NEW.evidence_id\n     AND EXISTS(SELECT 1 FROM claim_withdrawals w WHERE w.tenant_id=NEW.tenant_id AND w.receipt_id=r.id AND w.claim_id=NEW.evidence_id))\n    OR (r.operation='ai.run.revert' AND r.subject_type='agent_run' AND r.subject_id=NEW.run_id AND NEW.origin='ai_draft'\n     AND EXISTS(SELECT 1 FROM agent_runs ar WHERE ar.tenant_id=NEW.tenant_id AND ar.id=NEW.run_id AND ar.requester_id=r.requester_id AND ar.revert_receipt_id=r.id AND ar.reverted_by=r.requester_id)))\n   OR EXISTS(SELECT 1 FROM proposal_decisions d JOIN proposal_submissions sub ON sub.tenant_id=d.tenant_id AND sub.id=d.submission_id\n    WHERE d.tenant_id=NEW.tenant_id AND d.category_id=NEW.category_id AND position(NEW.id::text IN sub.frozen_document::text)>0)\n   OR EXISTS(SELECT 1 FROM definition_specs s JOIN definition_revisions d ON d.tenant_id=s.tenant_id AND d.id=s.definition_id\n    WHERE s.tenant_id=NEW.tenant_id AND s.category_id=NEW.category_id AND d.sealed AND position(NEW.id::text IN s.source_refs::text)>0) THEN\n   RAISE EXCEPTION 'evidence link revert proof or consumption mismatch' USING ERRCODE='23514'; END IF;\n  IF r.operation='ai.run.revert' THEN\n   PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n   IF NOT EXISTS(SELECT 1 FROM action_receipts original JOIN agent_runs actual ON actual.tenant_id=original.tenant_id AND actual.id=original.agent_run_id\n     WHERE original.tenant_id=NEW.tenant_id AND original.id=NEW.receipt_id AND original.agent_run_id=NEW.run_id\n      AND original.operation='evidence.link.create' AND original.subject_type='evidence_link' AND original.subject_id=NEW.id\n      AND original.category_id=NEW.category_id AND original.actor_id=actual.writer_id AND original.requester_id=r.requester_id\n      AND actual.category_id=NEW.category_id AND actual.writer_id=NEW.writer_id AND actual.requester_id=r.requester_id)\n    OR (NEW.target_type='proposal_item' AND NOT EXISTS(SELECT 1 FROM proposal_items item JOIN proposals proposal\n     ON proposal.tenant_id=item.tenant_id AND proposal.id=item.proposal_id WHERE item.tenant_id=NEW.tenant_id AND item.id=NEW.target_id\n      AND NOT item.removed AND item.current_version=NEW.target_version AND proposal.owner_id=r.requester_id AND proposal.status IN ('draft','returned')))\n    OR (NEW.target_type='knowledge_entry' AND NOT EXISTS(SELECT 1 FROM category_knowledge_entries entry WHERE entry.tenant_id=NEW.tenant_id\n     AND entry.id=NEW.target_id AND entry.version=NEW.target_version AND EXISTS(SELECT 1 FROM category_knowledge_current current\n      WHERE current.tenant_id=entry.tenant_id AND current.category_id=entry.category_id AND current.current_entry_id=entry.id AND current.status='active')))\n    OR (NEW.target_type='definition_spec' AND NOT EXISTS(SELECT 1 FROM definition_specs spec JOIN definition_revisions definition\n     ON definition.tenant_id=spec.tenant_id AND definition.id=spec.definition_id WHERE spec.tenant_id=NEW.tenant_id AND spec.id=NEW.target_id\n      AND definition.revision=NEW.target_version AND NOT definition.sealed AND definition.status='draft')) THEN\n    RAISE EXCEPTION 'evidence link run revert target changed' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF r.operation='ai.run.revert' AND NEW.target_type='proposal_item' THEN\n   SELECT pp.* INTO STRICT p FROM proposals pp JOIN proposal_items ii ON ii.tenant_id=pp.tenant_id AND ii.proposal_id=pp.id\n    WHERE ii.tenant_id=NEW.tenant_id AND ii.id=NEW.target_id FOR UPDATE OF pp;\n   DELETE FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id;\n   INSERT INTO proposal_sources(id,tenant_id,category_id,proposal_id,source_type,source_id,source_version,privacy,ref_count,created_at)\n   SELECT gen_random_uuid(),NEW.tenant_id,NEW.category_id,p.id,source_type,source_id,source_version,privacy,ref_count,statement_timestamp()\n    FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id);\n   UPDATE proposals SET private_source_count=(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private'),\n    effective_visibility=CASE WHEN EXISTS(SELECT 1 FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private') THEN 'private' ELSE visibility END,\n    context_hint=true WHERE tenant_id=NEW.tenant_id AND id=p.id;\n  END IF;\n  RETURN NULL;\n END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n root=m3_evidence_root(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id,NEW.evidence_version);\n IF NEW.evidence_type='claim' THEN\n  IF NOT m3_claim_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_id) THEN RAISE EXCEPTION 'claim unreadable' USING ERRCODE='23514'; END IF;\n ELSIF NOT m3_evidence_source_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id) THEN\n  RAISE EXCEPTION 'link source unreadable' USING ERRCODE='23514';\n END IF;\n IF NOT m3_evidence_target_reader(NEW.tenant_id,NEW.category_id,NEW.target_type,NEW.target_id)\n  OR NOT category_access(NEW.tenant_id,NEW.category_id,true) THEN RAISE EXCEPTION 'link target unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  SELECT * INTO STRICT i FROM proposal_items WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT p FROM proposals WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=i.proposal_id;\n  IF i.current_version<>NEW.target_version OR i.removed OR p.status NOT IN ('draft','returned') OR p.owner_id<>r.requester_id THEN\n   RAISE EXCEPTION 'link proposal target mismatch' USING ERRCODE='23514'; END IF;\n  target_proposal=p.id; shared=p.effective_visibility<>'private';\n ELSIF NEW.target_type='knowledge_entry' THEN\n  SELECT * INTO STRICT k FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  IF k.version<>NEW.target_version OR NOT EXISTS(SELECT 1 FROM category_knowledge_current cur WHERE cur.tenant_id=k.tenant_id\n   AND cur.category_id=k.category_id AND cur.current_entry_id=k.id AND cur.status='active') THEN\n   RAISE EXCEPTION 'link knowledge target mismatch' USING ERRCODE='23514'; END IF;\n  shared=true;\n ELSE\n  SELECT * INTO STRICT target_link_spec FROM definition_specs WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT def FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=target_link_spec.definition_id FOR UPDATE;\n  IF def.sealed OR def.status<>'draft' OR def.revision<>NEW.target_version THEN\n   RAISE EXCEPTION 'link sealed definition target mismatch' USING ERRCODE='23514'; END IF;\n  target_product=def.product_id;\n  shared=def.visibility<>'private' AND EXISTS(SELECT 1 FROM products pr WHERE pr.tenant_id=def.tenant_id AND pr.id=def.product_id AND pr.visibility<>'private');\n END IF;\n IF (shared AND ((root->>'private')::boolean OR coalesce((root->>'claim_private')::boolean,false)))\n  OR (coalesce((root->>'claim_private')::boolean,false) AND (root->>'proposal_id')::uuid IS DISTINCT FROM target_proposal) THEN\n  RAISE EXCEPTION 'private evidence cannot enter shared target' USING ERRCODE='23514'; END IF;\n IF r.operation<>'evidence.link.create' OR r.subject_type<>'evidence_link' OR r.subject_id<>NEW.id OR r.subject_revision<>1\n  OR r.category_id<>NEW.category_id OR r.product_id IS DISTINCT FROM target_product OR r.actor_id IS DISTINCT FROM scope_actor()\n  OR r.requester_id IS DISTINCT FROM scope_requester() OR r.agent_run_id IS DISTINCT FROM NEW.run_id\n  OR NEW.confirmed_by IS NOT NULL OR r.run_id IS NOT NULL OR r.confirmation_id IS NOT NULL\n  OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n     (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence link receipt mismatch' USING ERRCODE='23514'; END IF;\n IF NEW.origin='human' THEN\n  IF NEW.writer_id<>r.actor_id OR r.actor_id<>r.requester_id OR NEW.run_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals pr WHERE pr.tenant_id=NEW.tenant_id AND pr.id=NEW.writer_id AND pr.kind='human' AND pr.active) THEN\n   RAISE EXCEPTION 'evidence link human provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSIF NEW.origin='ai_draft' THEN\n  SELECT * INTO STRICT actual_link_run FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;\n  IF actual_link_run.category_id<>NEW.category_id OR actual_link_run.product_id IS DISTINCT FROM target_product OR actual_link_run.writer_id<>NEW.writer_id\n   OR actual_link_run.requester_id<>r.requester_id OR actual_link_run.writer_id<>r.actor_id OR actual_link_run.reverted_at IS NOT NULL OR actual_link_run.state='cancelled'\n   OR (target_proposal IS NOT NULL AND actual_link_run.proposal_id IS DISTINCT FROM target_proposal)\n   OR (target_proposal IS NULL AND actual_link_run.private_context)\n   OR NOT EXISTS(SELECT 1 FROM agent_tool_calls tc WHERE tc.tenant_id=NEW.tenant_id AND tc.run_id=NEW.run_id\n    AND tc.receipt_id=r.id AND tc.state='completed' AND tc.execution_binding->>'operation'=r.operation) THEN\n   RAISE EXCEPTION 'evidence link T0 provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'evidence link imported path unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  IF NOT EXISTS(SELECT 1 FROM proposal_revisions document_revision\n    JOIN action_receipts actual_receipt ON actual_receipt.tenant_id=document_revision.tenant_id AND actual_receipt.id=document_revision.receipt_id\n    JOIN proposals current_proposal ON current_proposal.tenant_id=document_revision.tenant_id AND current_proposal.id=document_revision.proposal_id\n    JOIN evidence_links actual_link ON actual_link.tenant_id=actual_receipt.tenant_id AND actual_link.id=actual_receipt.subject_id\n    WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.category_id=NEW.category_id\n     AND document_revision.proposal_id=p.id AND document_revision.receipt_id=r.id\n     AND document_revision.revision=current_proposal.revision AND document_revision.changed_items='[]'::jsonb\n     AND document_revision.actor_id=r.actor_id AND document_revision.run_id IS NOT DISTINCT FROM r.agent_run_id\n     AND actual_link.id=NEW.id AND actual_link.receipt_id=r.id\n     AND document_revision.xmin=actual_receipt.xmin AND current_proposal.xmin=actual_receipt.xmin AND actual_link.xmin=actual_receipt.xmin\n     AND EXISTS(SELECT 1 FROM proposal_revisions prior WHERE prior.tenant_id=document_revision.tenant_id\n      AND prior.proposal_id=document_revision.proposal_id AND prior.revision=document_revision.revision-1))\n   OR (SELECT count(*) FROM proposal_revisions document_revision WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.receipt_id=r.id)<>1\n   OR p.private_source_count<>(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private')\n   OR p.effective_visibility IS DISTINCT FROM (CASE WHEN p.private_source_count>0 THEN 'private' ELSE p.visibility END)\n   OR EXISTS((SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id)\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id)\n     UNION ALL (SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id))) THEN\n   RAISE EXCEPTION 'evidence link missing proposal revision or projection' USING ERRCODE='23514'; END IF;\n END IF;\n RETURN NULL;\nEND $function$\n"

PREDECESSOR_M3_MATERIAL_CONFIRMATION_GUARD = "CREATE OR REPLACE FUNCTION public.m3_material_confirmation_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE old_material boolean=false; new_material boolean=false;\nBEGIN\n IF TG_OP<>'INSERT' THEN\n  old_material=OLD.operation IN ('category.knowledge.add','category.knowledge.withdraw',\n   'category.knowledge.promote','category.parameter.publish','evidence.claim.record','evidence.claim.withdraw','proposal.share','ai.run.revert');\n END IF;\n IF TG_OP<>'DELETE' THEN\n  new_material=NEW.operation IN ('category.knowledge.add','category.knowledge.withdraw',\n   'category.knowledge.promote','category.parameter.publish','evidence.claim.record','evidence.claim.withdraw','proposal.share','ai.run.revert');\n END IF;\n IF old_material OR new_material THEN\n  IF TG_OP='DELETE' THEN\n   RAISE EXCEPTION 'material confirmation must be retained' USING ERRCODE='23514';\n  ELSIF TG_OP='INSERT' THEN\n   IF NEW.consumed IS DISTINCT FROM false THEN\n    RAISE EXCEPTION 'material confirmation starts unconsumed' USING ERRCODE='23514';\n   END IF;\n  ELSIF OLD.consumed IS DISTINCT FROM false OR NEW.consumed IS DISTINCT FROM true\n   OR (to_jsonb(NEW)-'consumed') IS DISTINCT FROM (to_jsonb(OLD)-'consumed') THEN\n   RAISE EXCEPTION 'material confirmation can only be consumed once' USING ERRCODE='23514';\n  END IF;\n END IF;\n IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n RETURN NEW;\nEND $function$\n"

PREDECESSOR_M3_EVIDENCE_RUN_REVERT_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_run_revert_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; original action_receipts; ids uuid[]; targets jsonb; expected_ids jsonb; rx xid;\nBEGIN\n IF NEW.revert_receipt_id IS NOT DISTINCT FROM OLD.revert_receipt_id THEN RETURN NULL; END IF;\n -- Existing S0-only run semantics remain with their original owner.\n IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.run_id=NEW.id)\n  AND NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.run_id=NEW.id AND k.receipt_id IS NOT NULL) THEN RETURN NULL; END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.revert_receipt_id;\n PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id;\n IF r.operation IS DISTINCT FROM 'ai.run.revert' OR r.subject_type IS DISTINCT FROM 'agent_run' OR r.subject_id IS DISTINCT FROM NEW.id\n  OR r.actor_id IS DISTINCT FROM scope_actor() OR r.requester_id IS DISTINCT FROM NEW.requester_id\n  OR r.actor_id IS DISTINCT FROM r.requester_id OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n  OR r.category_id IS DISTINCT FROM NEW.category_id OR r.product_id IS DISTINCT FROM NEW.product_id\n  OR rx IS DISTINCT FROM (SELECT xmin FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence run revert identity mismatch' USING ERRCODE='23514'; END IF;\n SELECT coalesce(array_agg(receipt.id ORDER BY receipt.id),'{}'::uuid[]),\n  coalesce(jsonb_agg(jsonb_build_object('type',receipt.subject_type,'id',receipt.subject_id) ORDER BY receipt.id),'[]'::jsonb),\n  coalesce(jsonb_agg(to_jsonb(receipt.id) ORDER BY receipt.id),'[]'::jsonb)\n INTO ids,targets,expected_ids FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id;\n IF jsonb_typeof(r.result->'receipt_ids') IS DISTINCT FROM 'array'\n  OR (SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) FROM jsonb_array_elements(r.result->'receipt_ids')) IS DISTINCT FROM expected_ids\n  OR revert_subjects_consumed(NEW.tenant_id,NEW.category_id,targets,ids) THEN\n  RAISE EXCEPTION 'evidence run revert incomplete or consumed' USING ERRCODE='23514'; END IF;\n FOR original IN SELECT receipt.* FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id LOOP\n  IF original.subject_type='claim' THEN\n   IF NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.id=original.subject_id\n    AND k.status='reverted' AND k.revision=original.subject_revision+1 AND k.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing claim' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='artifact' THEN\n   IF NOT EXISTS(SELECT 1 FROM artifact_versions a WHERE a.tenant_id=NEW.tenant_id AND a.id=original.subject_id\n    AND a.status='withdrawn' AND a.revision=original.subject_revision+1 AND a.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing artifact' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='evidence_link' THEN\n   IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.id=original.subject_id\n    AND l.reverted_by_receipt_id=r.id AND l.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing link' USING ERRCODE='23514'; END IF;\n  ELSE RAISE EXCEPTION 'evidence run revert unsupported result' USING ERRCODE='23514'; END IF;\n END LOOP;\n RETURN NULL;\nEND $function$\n"

FIXED_GUARD = "CREATE OR REPLACE FUNCTION public.protect_fixed_definition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n BEGIN\n IF TG_TABLE_NAME='definition_specs' AND TG_OP='UPDATE'\n  AND OLD.receipt_id IS NULL AND NEW.receipt_id IS NOT NULL\n  AND (to_jsonb(NEW)-'receipt_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'receipt_id')\n  AND EXISTS(SELECT 1 FROM action_receipts receipt JOIN definition_specs spec\n   ON spec.tenant_id=receipt.tenant_id AND spec.id=NEW.id AND spec.xmin=receipt.xmin\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.id=NEW.receipt_id\n    AND receipt.operation IN ('product.definition.item.patch','product.definition.draft')\n    AND receipt.subject_id=NEW.definition_id AND receipt.subject_type='definition_revision'\n    AND receipt.category_id=NEW.category_id AND receipt.product_id=NEW.product_id\n    AND receipt.actor_id=scope_actor() AND receipt.requester_id=scope_requester()) THEN RETURN NEW; END IF;\n IF TG_TABLE_NAME='definition_revisions' AND TG_OP='UPDATE' AND current_user='pdos_next_owner'\n  AND OLD.status='draft' AND NOT OLD.sealed AND NEW.status='published' AND NEW.sealed\n  AND (to_jsonb(NEW)-ARRAY['status','sealed','publication_receipt_id']) IS NOT DISTINCT FROM\n      (to_jsonb(OLD)-ARRAY['status','sealed','publication_receipt_id']) THEN RETURN NEW; END IF;\n IF TG_OP='UPDATE' AND TG_TABLE_NAME='definition_revisions'\n AND (to_jsonb(OLD)->>'sealed')='false' AND (to_jsonb(NEW)->>'sealed')='true'\n AND (to_jsonb(NEW)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n   =(to_jsonb(OLD)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n AND m3_result_access(NEW.tenant_id,NEW.category_id,'definition_revisions',NEW.id)\n THEN RETURN NEW; END IF;\n RAISE EXCEPTION 'definition snapshots are immutable'; END $function$\n"

G0_ASSERT = "CREATE OR REPLACE FUNCTION public.m3_g0_derivation_assert(t uuid, c uuid, did uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE decision proposal_decisions; proposal proposals; submission proposal_submissions; definition definition_revisions;\n model products; variant product_variants; variant_version variant_revisions; project projects; receipt action_receipts;\n rx xid; spec_item jsonb; expected_spec definition_specs; actual_spec definition_specs; spec_count bigint;\n expected_claims jsonb; frozen_claims jsonb; baseline_claim jsonb;\nBEGIN\n SELECT * INTO STRICT decision FROM proposal_decisions WHERE tenant_id=t AND category_id=c AND id=did;\n IF decision.outcome<>'approved' THEN RETURN; END IF;\n SELECT * INTO STRICT proposal FROM proposals WHERE tenant_id=t AND category_id=c AND id=decision.proposal_id;\n SELECT * INTO STRICT submission FROM proposal_submissions WHERE tenant_id=t AND category_id=c AND id=decision.submission_id;\n SELECT * INTO STRICT receipt FROM action_receipts WHERE tenant_id=t AND category_id=c AND id=decision.receipt_id;\n SELECT * INTO STRICT definition FROM definition_revisions WHERE tenant_id=t AND category_id=c AND id=decision.created_definition_id;\n SELECT * INTO STRICT model FROM products WHERE tenant_id=t AND category_id=c AND id=decision.created_product_id FOR UPDATE;\n SELECT * INTO STRICT project FROM projects WHERE tenant_id=t AND category_id=c AND id=decision.created_project_id;\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=t AND id=receipt.id;\n IF receipt.operation IS DISTINCT FROM 'proposal.g0.decide' OR receipt.subject_type IS DISTINCT FROM 'proposal'\n  OR receipt.subject_id IS DISTINCT FROM proposal.id OR receipt.actor_id IS DISTINCT FROM decision.decided_by\n  OR receipt.subject_revision IS DISTINCT FROM proposal.revision\n  OR receipt.requester_id IS DISTINCT FROM decision.decided_by OR receipt.actor_id IS DISTINCT FROM scope_actor()\n  OR scope_actor() IS DISTINCT FROM scope_requester() OR category_access(t,c) IS DISTINCT FROM true\n  OR NOT EXISTS(SELECT 1 FROM grants grant_row JOIN principals signer ON signer.tenant_id=grant_row.tenant_id AND signer.id=grant_row.principal_id\n   WHERE grant_row.tenant_id=t AND grant_row.category_id=c AND grant_row.principal_id=decision.decided_by\n    AND grant_row.product_manager AND (grant_row.expires_at IS NULL OR grant_row.expires_at>statement_timestamp())\n    AND signer.active AND signer.kind='human')\n  OR receipt.agent_run_id IS NOT NULL OR receipt.run_id IS NOT NULL OR receipt.product_id IS NOT NULL\n  OR submission.proposal_id IS DISTINCT FROM proposal.id OR submission.reviewer_id IS DISTINCT FROM decision.decided_by\n  OR proposal.current_submission_id IS DISTINCT FROM submission.id OR decision.review_digest IS DISTINCT FROM submission.document_digest\n  OR definition.product_id IS DISTINCT FROM model.id OR definition.g0_decision_id IS DISTINCT FROM decision.id\n  OR definition.variant_id IS DISTINCT FROM decision.created_variant_id OR definition.revision<>1 OR NOT definition.sealed OR definition.status<>'draft'\n  OR definition.source_proposal_id IS DISTINCT FROM proposal.id OR definition.source_submission_id IS DISTINCT FROM submission.id\n  OR definition.source_proposal_revision IS DISTINCT FROM submission.revision OR definition.owner_id IS DISTINCT FROM proposal.owner_id\n  OR definition.visibility IS DISTINCT FROM proposal.effective_visibility\n  OR project.product_id IS DISTINCT FROM model.id OR project.g0_decision_id IS DISTINCT FROM decision.id OR project.owner_id IS DISTINCT FROM decision.project_owner_id\n  OR project.visibility IS DISTINCT FROM proposal.effective_visibility\n  OR rx::text::bigint IS DISTINCT FROM txid_current()%4294967296\n  OR rx IS DISTINCT FROM (SELECT xmin FROM proposal_decisions WHERE tenant_id=t AND id=decision.id)\n  OR rx IS DISTINCT FROM (SELECT xmin FROM proposals WHERE tenant_id=t AND id=proposal.id)\n  OR rx IS DISTINCT FROM (SELECT xmin FROM definition_revisions WHERE tenant_id=t AND id=definition.id)\n  OR rx IS DISTINCT FROM (SELECT xmin FROM projects WHERE tenant_id=t AND id=project.id)\n  OR receipt.result->>'decision_id' IS DISTINCT FROM decision.id::text OR receipt.result->>'product_id' IS DISTINCT FROM model.id::text\n  OR receipt.result->>'definition_id' IS DISTINCT FROM definition.id::text OR receipt.result->>'project_id' IS DISTINCT FROM project.id::text\n  OR NOT EXISTS(SELECT 1 FROM project_product_links link WHERE link.tenant_id=t AND link.category_id=c AND link.project_id=project.id\n   AND link.product_id=model.id AND link.definition_id=definition.id AND link.definition_revision=definition.revision\n   AND link.variant_id IS NOT DISTINCT FROM definition.variant_id AND link.xmin=rx) THEN\n  RAISE EXCEPTION 'G0 derivation outputs require exact same transaction named receipt' USING ERRCODE='23514'; END IF;\n IF proposal.entry_kind='derivative' OR proposal.target_kind='new_variant' THEN\n  IF m3_published_baseline_valid(t,c,proposal.baseline_product_id,proposal.baseline_definition_id,proposal.baseline_definition_revision) IS DISTINCT FROM true\n   OR definition.derived_from_definition_id IS DISTINCT FROM proposal.baseline_definition_id\n   OR definition.derived_from_definition_revision IS DISTINCT FROM proposal.baseline_definition_revision\n   OR submission.frozen_document->>'baseline_product_id' IS DISTINCT FROM proposal.baseline_product_id::text\n   OR submission.frozen_document->>'baseline_definition_id' IS DISTINCT FROM proposal.baseline_definition_id::text\n   OR (submission.frozen_document->>'baseline_definition_revision')::integer IS DISTINCT FROM proposal.baseline_definition_revision\n   OR NOT EXISTS(SELECT 1 FROM definition_revisions baseline JOIN products parent ON parent.tenant_id=baseline.tenant_id AND parent.id=baseline.product_id\n    WHERE baseline.tenant_id=t AND baseline.category_id=c AND baseline.id=proposal.baseline_definition_id\n     AND source_object_audience(t,c,'definition_revisions',baseline.id,baseline.owner_id,baseline.visibility)\n     AND source_object_audience(t,c,'products',parent.id,parent.owner_id,parent.visibility)\n     AND (proposal.effective_visibility='private' OR (baseline.visibility='category' AND parent.visibility='category' AND m3_definition_root_private(t,c,baseline.id,proposal.baseline_definition_revision) IS FALSE))) THEN\n   RAISE EXCEPTION 'G0 derivation baseline must be actual readable fixed publication' USING ERRCODE='23514'; END IF;\n  -- The dependency set comes from persisted source edges, not a caller's\n  -- declaration. The frozen document and actual signed consumption must both\n  -- contain the complete recursive Claim closure of the fixed parent.\n  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)\n   ORDER BY jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)),'[]') INTO expected_claims\n   FROM jsonb_array_elements(m3_baseline_reference_graph(t,c,proposal.baseline_definition_id,proposal.baseline_definition_revision)) ref\n   WHERE ref->>'type'='claim';\n  IF jsonb_typeof(coalesce(submission.frozen_document->'baseline_claim_refs','[]')) IS DISTINCT FROM 'array' THEN\n   RAISE EXCEPTION 'G0 baseline claim closure differs from fixed publication' USING ERRCODE='23514'; END IF;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(submission.frozen_document->'baseline_claim_refs','[]')) ref\n   WHERE ref->>'type' IS DISTINCT FROM 'claim' OR ref->>'id' IS NULL OR ref->>'version' IS NULL) THEN\n   RAISE EXCEPTION 'G0 baseline claim closure differs from fixed publication' USING ERRCODE='23514'; END IF;\n  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)\n   ORDER BY jsonb_build_object('id',(ref->>'id')::uuid,'version',(ref->>'version')::integer)),'[]') INTO frozen_claims\n   FROM jsonb_array_elements(coalesce(submission.frozen_document->'baseline_claim_refs','[]')) ref;\n  IF frozen_claims IS DISTINCT FROM expected_claims THEN\n   RAISE EXCEPTION 'G0 baseline claim closure differs from fixed publication' USING ERRCODE='23514'; END IF;\n  FOR baseline_claim IN SELECT ref FROM jsonb_array_elements(expected_claims) ref LOOP\n   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(submission.frozen_document->'source_refs','[]')) ref\n    WHERE ref->>'type'='claim' AND (ref->>'id')::uuid=(baseline_claim->>'id')::uuid\n     AND (ref->>'version')::integer=(baseline_claim->>'version')::integer)\n    OR (SELECT count(*) FROM claim_consumptions consumption\n     WHERE consumption.tenant_id=t AND consumption.category_id=c AND consumption.product_id=model.id\n      AND consumption.claim_id=(baseline_claim->>'id')::uuid AND consumption.claim_version=(baseline_claim->>'version')::integer\n      AND consumption.decision_id=decision.id AND consumption.definition_id=definition.id\n      AND consumption.receipt_id=receipt.id AND consumption.consumer_id=decision.id AND consumption.xmin=rx)<>1 THEN\n    RAISE EXCEPTION 'G0 baseline claim consumption must commit with decision' USING ERRCODE='23514'; END IF;\n  END LOOP;\n ELSE\n  IF definition.derived_from_definition_id IS NOT NULL OR definition.derived_from_definition_revision IS NOT NULL\n   OR proposal.baseline_product_id IS NOT NULL OR proposal.baseline_definition_id IS NOT NULL OR proposal.baseline_definition_revision IS NOT NULL THEN\n   RAISE EXCEPTION 'new product has no derivation baseline' USING ERRCODE='23514'; END IF;\n END IF;\n IF proposal.target_kind='new_variant' THEN\n  IF (SELECT count(*) FROM product_variants actual_variant\n   JOIN variant_revisions actual_version ON actual_version.tenant_id=actual_variant.tenant_id\n    AND actual_version.category_id=actual_variant.category_id AND actual_version.variant_id=actual_variant.id\n   WHERE actual_variant.tenant_id=t AND actual_variant.category_id=c AND actual_variant.id=decision.created_variant_id\n    AND actual_variant.product_id=model.id AND actual_variant.g0_decision_id=decision.id AND actual_variant.xmin=rx\n    AND actual_version.product_id=model.id AND actual_version.definition_id=definition.id\n    AND actual_version.revision=1 AND actual_version.xmin=rx\n    AND actual_version.parent_definition_id=proposal.baseline_definition_id\n    AND actual_version.parent_revision=proposal.baseline_definition_revision\n    AND actual_version.effective_definition=jsonb_build_object('definition_id',definition.id,'definition_revision',definition.revision))<>1 THEN\n   RAISE EXCEPTION 'G0 variant canonical definition mismatch' USING ERRCODE='23514'; END IF;\n  SELECT * INTO variant FROM product_variants WHERE tenant_id=t AND category_id=c AND id=decision.created_variant_id;\n  SELECT * INTO variant_version FROM variant_revisions WHERE tenant_id=t AND category_id=c AND variant_id=variant.id AND revision=1;\n  IF variant.id IS NULL OR variant_version.id IS NULL OR model.id IS DISTINCT FROM proposal.baseline_product_id OR variant.product_id IS DISTINCT FROM model.id\n   OR variant.g0_decision_id IS DISTINCT FROM decision.id OR variant.owner_id IS DISTINCT FROM proposal.owner_id\n   OR variant.visibility IS DISTINCT FROM proposal.effective_visibility OR variant_version.visibility IS DISTINCT FROM proposal.effective_visibility\n   OR variant_version.definition_id IS DISTINCT FROM definition.id OR variant_version.product_id IS DISTINCT FROM model.id\n   OR variant_version.owner_id IS DISTINCT FROM proposal.owner_id OR variant_version.parent_definition_id IS DISTINCT FROM proposal.baseline_definition_id\n   OR variant_version.parent_revision IS DISTINCT FROM proposal.baseline_definition_revision\n   OR variant_version.previous_revision_id IS NOT NULL\n   OR variant_version.sources IS DISTINCT FROM jsonb_build_array(jsonb_build_object('type','definition','id',proposal.baseline_definition_id,'version',proposal.baseline_definition_revision))\n   OR variant_version.effective_definition IS DISTINCT FROM jsonb_build_object('definition_id',definition.id,'definition_revision',definition.revision)\n   OR rx IS DISTINCT FROM (SELECT xmin FROM product_variants WHERE tenant_id=t AND id=variant.id)\n   OR rx IS DISTINCT FROM (SELECT xmin FROM variant_revisions WHERE tenant_id=t AND id=variant_version.id)\n   OR receipt.result->>'variant_id' IS DISTINCT FROM variant.id::text THEN\n   RAISE EXCEPTION 'G0 variant canonical definition mismatch' USING ERRCODE='23514'; END IF;\n ELSIF proposal.target_kind='new_product' THEN\n  IF decision.created_variant_id IS NOT NULL OR definition.variant_id IS NOT NULL\n   OR rx IS DISTINCT FROM (SELECT xmin FROM products WHERE tenant_id=t AND id=model.id) OR model.visibility IS DISTINCT FROM proposal.effective_visibility\n   OR model.parent_product_id IS DISTINCT FROM (CASE WHEN proposal.entry_kind='derivative' THEN proposal.baseline_product_id ELSE NULL END)\n   OR (proposal.baseline_product_id IS NOT NULL AND model.id=proposal.baseline_product_id) THEN\n   RAISE EXCEPTION 'G0 new product identity or derivation mismatch' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'unknown G0 target scope' USING ERRCODE='23514'; END IF;\n -- Canonical specification facts are exactly the fixed submitted items,\n -- including human-value and AI provenance fields; JSON numeric strings are\n -- coerced through the actual row type before comparison.\n SELECT count(*) INTO spec_count FROM jsonb_array_elements(submission.frozen_document->'items') item WHERE item->>'kind'='spec';\n IF spec_count<>(SELECT count(*) FROM definition_specs spec WHERE spec.tenant_id=t AND spec.definition_id=definition.id) THEN\n  RAISE EXCEPTION 'G0 canonical specification set differs from submission' USING ERRCODE='23514'; END IF;\n FOR spec_item IN SELECT item FROM jsonb_array_elements(submission.frozen_document->'items') item WHERE item->>'kind'='spec' LOOP\n  SELECT * INTO STRICT actual_spec FROM definition_specs WHERE tenant_id=t AND category_id=c AND definition_id=definition.id AND key=spec_item->'content'->>'key';\n  IF actual_spec.item_id IS DISTINCT FROM actual_spec.id OR actual_spec.item_version IS DISTINCT FROM 1\n   OR actual_spec.removed IS DISTINCT FROM false OR actual_spec.prepared_candidate_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=t\n    AND current.category_id=c AND current.product_id=definition.product_id AND current.definition_id=definition.id\n    AND current.id=actual_spec.id AND current.item_id=actual_spec.id AND current.current_row_id=actual_spec.id\n    AND current.current_version=1 AND current.key=actual_spec.key AND NOT current.removed) THEN\n   RAISE EXCEPTION 'G0 specification must retain initial exact current identity' USING ERRCODE='23514'; END IF;\n  SELECT * INTO expected_spec FROM jsonb_populate_record(NULL::definition_specs,(spec_item->'content')||jsonb_build_object(\n   'text',spec_item->'content'->'text_value','method',spec_item->'content'->'verification_method','state','proposed',\n   'test_conditions',coalesce(spec_item->'content'->'test_conditions','[]'::jsonb),\n   'reason',coalesce(spec_item->'content'->>'reason',''),'source_refs',spec_item->'source_refs','origin',spec_item->>'origin',\n   'writer_id',spec_item->'writer_id','run_id',spec_item->'run_id','confirmed_by',spec_item->'confirmed_by','receipt_id',receipt.id));\n  IF (to_jsonb(actual_spec)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','prepared_candidate_id']) IS DISTINCT FROM\n     (to_jsonb(expected_spec)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','prepared_candidate_id']) THEN\n   RAISE EXCEPTION 'G0 canonical specification differs from frozen human value or provenance' USING ERRCODE='23514'; END IF;\n END LOOP;\n -- The deferred atom sees the complete persisted canonical graph, after the\n -- INSERT RETURNING statement-snapshot window has closed.\n IF definition_sources_visible(t,c,model.id,definition.id) IS DISTINCT FROM true THEN\n  RAISE EXCEPTION 'G0 canonical definition sources are not currently readable' USING ERRCODE='23514'; END IF;\nEND $function$\n"

REFERENCE_GRAPH = "CREATE OR REPLACE FUNCTION public.m3_reference_graph(t uuid, c uuid, seeds jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE queue jsonb;\n refs jsonb='[]'; cursor_index integer=0; node jsonb; ref jsonb; path jsonb; token text; children jsonb;\nBEGIN\n IF jsonb_typeof(seeds) IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;\n SELECT coalesce(jsonb_agg(jsonb_build_object('ref',seed,'path','[]'::jsonb)),'[]')\n  INTO queue FROM jsonb_array_elements(seeds) seed;\n WHILE cursor_index<jsonb_array_length(queue) LOOP\n  node=queue->cursor_index; cursor_index=cursor_index+1; ref=node->'ref'; path=node->'path';\n  IF jsonb_typeof(ref) IS DISTINCT FROM 'object'\n   OR coalesce(ref->>'type','')<>ALL(ARRAY['artifact','original','snapshot','claim','knowledge','definition','parameter','human'])\n   OR jsonb_typeof(ref->'id') IS DISTINCT FROM 'string'\n   OR jsonb_typeof(ref->'version') IS DISTINCT FROM 'number'\n   OR (ref->>'version')::integer<1 THEN RETURN NULL; END IF;\n  token=(ref->>'type')||':'||(ref->>'id')||':'||(ref->>'version');\n  IF token IS NULL OR path ? token THEN RETURN NULL; END IF;\n  refs=refs||jsonb_build_array(ref); path=path||jsonb_build_array(token); children='[]';\n  IF ref->>'type'='definition' THEN\n   IF NOT EXISTS(SELECT 1 FROM definition_revisions d WHERE d.tenant_id=t AND d.category_id=c\n    AND d.id=(ref->>'id')::uuid AND d.revision=(ref->>'version')::integer) THEN RETURN NULL; END IF;\n   SELECT coalesce(jsonb_agg(source),'[]') INTO children FROM (\n    SELECT jsonb_build_object('type','artifact','id',s.artifact_id,'version',s.source_revision,'line',s.line,'quote',s.quote) source\n     FROM definition_sources s WHERE s.tenant_id=t AND s.category_id=c AND s.definition_id=(ref->>'id')::uuid\n    UNION ALL SELECT item FROM definition_specs spec\n     JOIN definition_spec_current current ON current.tenant_id=spec.tenant_id AND current.category_id=spec.category_id\n      AND current.product_id=spec.product_id AND current.definition_id=spec.definition_id\n      AND current.item_id=spec.item_id AND current.current_row_id=spec.id\n      AND current.current_version=spec.item_version AND NOT current.removed\n     CROSS JOIN LATERAL jsonb_array_elements(spec.source_refs) item\n     WHERE spec.tenant_id=t AND spec.category_id=c AND spec.definition_id=(ref->>'id')::uuid\n    UNION ALL SELECT jsonb_build_object('type','definition','id',d.derived_from_definition_id,'version',d.derived_from_definition_revision)\n     FROM definition_revisions d WHERE d.tenant_id=t AND d.category_id=c AND d.id=(ref->>'id')::uuid AND d.derived_from_definition_id IS NOT NULL\n    UNION ALL SELECT jsonb_build_object('type','definition','id',parent.id,'version',parent.revision)\n     FROM definition_revisions d JOIN definition_revisions parent ON parent.tenant_id=d.tenant_id AND parent.category_id=d.category_id AND parent.id=d.parent_definition_id\n     WHERE d.tenant_id=t AND d.category_id=c AND d.id=(ref->>'id')::uuid\n   ) edges;\n  ELSIF ref->>'type'='knowledge' THEN\n   IF NOT EXISTS(SELECT 1 FROM category_knowledge_entries knowledge\n    WHERE knowledge.tenant_id=t AND knowledge.category_id=c AND knowledge.id=(ref->>'id')::uuid\n     AND knowledge.version=(ref->>'version')::integer) THEN RETURN NULL; END IF;\n   -- Mirror category_service._references, never arbitrary nested dictionaries.\n   SELECT coalesce(jsonb_agg(edge),'[]') INTO children FROM category_knowledge_entries knowledge\n    CROSS JOIN LATERAL (\n     SELECT item AS edge FROM jsonb_array_elements(knowledge.source_refs) item\n     UNION ALL SELECT item FROM jsonb_array_elements(CASE WHEN knowledge.kind='voice'\n      THEN coalesce(knowledge.content->'representative_refs','[]') ELSE '[]'::jsonb END) item\n     UNION ALL SELECT item->'source_ref' FROM jsonb_array_elements(CASE WHEN knowledge.kind='competitor'\n      THEN coalesce(knowledge.content->'metrics','[]') || coalesce(knowledge.content->'features','[]')\n       || coalesce(knowledge.content->'prices','[]') ELSE '[]'::jsonb END) item\n      WHERE item->'source_ref' IS NOT NULL AND item->'source_ref'<>'null'::jsonb\n    ) registered\n    WHERE knowledge.tenant_id=t AND knowledge.category_id=c AND knowledge.id=(ref->>'id')::uuid\n     AND knowledge.version=(ref->>'version')::integer;\n  ELSIF ref->>'type'='claim' THEN\n   SELECT coalesce(jsonb_agg(jsonb_build_object('type',claim.source_kind,'id',coalesce(claim.artifact_id,claim.snapshot_id),\n    'version',claim.source_revision,'line',claim.line,'quote',claim.quote)),'[]') INTO children\n    FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=(ref->>'id')::uuid;\n  END IF;\n  SELECT queue||coalesce(jsonb_agg(jsonb_build_object('ref',child,'path',path)),'[]') INTO queue FROM jsonb_array_elements(children) child;\n END LOOP;\n RETURN (SELECT coalesce(jsonb_agg(DISTINCT item ORDER BY item),'[]') FROM jsonb_array_elements(refs) item);\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;\nEND $function$\n"

EVIDENCE_LINK_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_link_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; actual_link_run agent_runs; p proposals; i proposal_items; k category_knowledge_entries;\n target_link_spec definition_specs; def definition_revisions; root jsonb; shared boolean; target_product uuid; target_proposal uuid;\nBEGIN\n IF TG_OP='UPDATE' THEN\n  SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.reverted_by_receipt_id;\n  IF r.category_id<>NEW.category_id OR r.actor_id<>r.requester_id OR r.actor_id IS DISTINCT FROM scope_actor()\n   OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n   OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n      (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id)\n   OR NOT ( (r.operation='evidence.claim.withdraw' AND NEW.evidence_type='claim' AND r.subject_id=NEW.evidence_id\n     AND EXISTS(SELECT 1 FROM claim_withdrawals w WHERE w.tenant_id=NEW.tenant_id AND w.receipt_id=r.id AND w.claim_id=NEW.evidence_id))\n    OR (r.operation='ai.run.revert' AND r.subject_type='agent_run' AND r.subject_id=NEW.run_id AND NEW.origin='ai_draft'\n     AND EXISTS(SELECT 1 FROM agent_runs ar WHERE ar.tenant_id=NEW.tenant_id AND ar.id=NEW.run_id AND ar.requester_id=r.requester_id AND ar.revert_receipt_id=r.id AND ar.reverted_by=r.requester_id)))\n   OR EXISTS(SELECT 1 FROM proposal_decisions d JOIN proposal_submissions sub ON sub.tenant_id=d.tenant_id AND sub.id=d.submission_id\n    WHERE d.tenant_id=NEW.tenant_id AND d.category_id=NEW.category_id AND position(NEW.id::text IN sub.frozen_document::text)>0)\n   OR EXISTS(SELECT 1 FROM definition_specs s JOIN definition_revisions d ON d.tenant_id=s.tenant_id AND d.id=s.definition_id\n    WHERE s.tenant_id=NEW.tenant_id AND s.category_id=NEW.category_id AND d.sealed AND position(NEW.id::text IN s.source_refs::text)>0) THEN\n   RAISE EXCEPTION 'evidence link revert proof or consumption mismatch' USING ERRCODE='23514'; END IF;\n  IF r.operation='ai.run.revert' THEN\n   PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n   IF NOT EXISTS(SELECT 1 FROM action_receipts original JOIN agent_runs actual ON actual.tenant_id=original.tenant_id AND actual.id=original.agent_run_id\n     WHERE original.tenant_id=NEW.tenant_id AND original.id=NEW.receipt_id AND original.agent_run_id=NEW.run_id\n      AND original.operation='evidence.link.create' AND original.subject_type='evidence_link' AND original.subject_id=NEW.id\n      AND original.category_id=NEW.category_id AND original.actor_id=actual.writer_id AND original.requester_id=r.requester_id\n      AND actual.category_id=NEW.category_id AND actual.writer_id=NEW.writer_id AND actual.requester_id=r.requester_id)\n    OR (NEW.target_type='proposal_item' AND NOT EXISTS(SELECT 1 FROM proposal_items item JOIN proposals proposal\n     ON proposal.tenant_id=item.tenant_id AND proposal.id=item.proposal_id WHERE item.tenant_id=NEW.tenant_id AND item.id=NEW.target_id\n      AND NOT item.removed AND item.current_version=NEW.target_version AND proposal.owner_id=r.requester_id AND proposal.status IN ('draft','returned')))\n    OR (NEW.target_type='knowledge_entry' AND NOT EXISTS(SELECT 1 FROM category_knowledge_entries entry WHERE entry.tenant_id=NEW.tenant_id\n     AND entry.id=NEW.target_id AND entry.version=NEW.target_version AND EXISTS(SELECT 1 FROM category_knowledge_current current\n      WHERE current.tenant_id=entry.tenant_id AND current.category_id=entry.category_id AND current.current_entry_id=entry.id AND current.status='active')))\n    OR (NEW.target_type='definition_spec' AND NOT EXISTS(SELECT 1 FROM definition_specs spec JOIN definition_revisions definition\n     ON definition.tenant_id=spec.tenant_id AND definition.id=spec.definition_id WHERE spec.tenant_id=NEW.tenant_id AND spec.id=NEW.target_id\n      AND definition.revision=NEW.target_version AND NOT definition.sealed AND definition.status='draft' AND EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=spec.tenant_id AND current.definition_id=spec.definition_id AND current.item_id=spec.item_id AND current.current_row_id=spec.id AND current.current_version=spec.item_version AND NOT current.removed))) THEN\n    RAISE EXCEPTION 'evidence link run revert target changed' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF r.operation='ai.run.revert' AND NEW.target_type='proposal_item' THEN\n   SELECT pp.* INTO STRICT p FROM proposals pp JOIN proposal_items ii ON ii.tenant_id=pp.tenant_id AND ii.proposal_id=pp.id\n    WHERE ii.tenant_id=NEW.tenant_id AND ii.id=NEW.target_id FOR UPDATE OF pp;\n   DELETE FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id;\n   INSERT INTO proposal_sources(id,tenant_id,category_id,proposal_id,source_type,source_id,source_version,privacy,ref_count,created_at)\n   SELECT gen_random_uuid(),NEW.tenant_id,NEW.category_id,p.id,source_type,source_id,source_version,privacy,ref_count,statement_timestamp()\n    FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id);\n   UPDATE proposals SET private_source_count=(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private'),\n    effective_visibility=CASE WHEN EXISTS(SELECT 1 FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private') THEN 'private' ELSE visibility END,\n    context_hint=true WHERE tenant_id=NEW.tenant_id AND id=p.id;\n  END IF;\n  RETURN NULL;\n END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n root=m3_evidence_root(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id,NEW.evidence_version);\n IF NEW.evidence_type='claim' THEN\n  IF NOT m3_claim_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_id) THEN RAISE EXCEPTION 'claim unreadable' USING ERRCODE='23514'; END IF;\n ELSIF NOT m3_evidence_source_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id) THEN\n  RAISE EXCEPTION 'link source unreadable' USING ERRCODE='23514';\n END IF;\n IF NOT m3_evidence_target_reader(NEW.tenant_id,NEW.category_id,NEW.target_type,NEW.target_id)\n  OR NOT category_access(NEW.tenant_id,NEW.category_id,true) THEN RAISE EXCEPTION 'link target unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  SELECT * INTO STRICT i FROM proposal_items WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT p FROM proposals WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=i.proposal_id;\n  IF i.current_version<>NEW.target_version OR i.removed OR p.status NOT IN ('draft','returned') OR p.owner_id<>r.requester_id THEN\n   RAISE EXCEPTION 'link proposal target mismatch' USING ERRCODE='23514'; END IF;\n  target_proposal=p.id; shared=p.effective_visibility<>'private';\n ELSIF NEW.target_type='knowledge_entry' THEN\n  SELECT * INTO STRICT k FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  IF k.version<>NEW.target_version OR NOT EXISTS(SELECT 1 FROM category_knowledge_current cur WHERE cur.tenant_id=k.tenant_id\n   AND cur.category_id=k.category_id AND cur.current_entry_id=k.id AND cur.status='active') THEN\n   RAISE EXCEPTION 'link knowledge target mismatch' USING ERRCODE='23514'; END IF;\n  shared=true;\n ELSE\n  SELECT * INTO STRICT target_link_spec FROM definition_specs WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT def FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=target_link_spec.definition_id FOR UPDATE;\n  IF def.sealed OR def.status<>'draft' OR def.revision<>NEW.target_version\n   OR NOT EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=target_link_spec.tenant_id\n    AND current.definition_id=target_link_spec.definition_id AND current.item_id=target_link_spec.item_id\n    AND current.current_row_id=target_link_spec.id AND current.current_version=target_link_spec.item_version AND NOT current.removed) THEN\n   RAISE EXCEPTION 'link sealed definition target mismatch' USING ERRCODE='23514'; END IF;\n  target_product=def.product_id;\n  shared=def.visibility<>'private' AND EXISTS(SELECT 1 FROM products pr WHERE pr.tenant_id=def.tenant_id AND pr.id=def.product_id AND pr.visibility<>'private');\n END IF;\n IF (shared AND ((root->>'private')::boolean OR coalesce((root->>'claim_private')::boolean,false)))\n  OR (coalesce((root->>'claim_private')::boolean,false) AND (root->>'proposal_id')::uuid IS DISTINCT FROM target_proposal) THEN\n  RAISE EXCEPTION 'private evidence cannot enter shared target' USING ERRCODE='23514'; END IF;\n IF r.operation<>'evidence.link.create' OR r.subject_type<>'evidence_link' OR r.subject_id<>NEW.id OR r.subject_revision<>1\n  OR r.category_id<>NEW.category_id OR r.product_id IS DISTINCT FROM target_product OR r.actor_id IS DISTINCT FROM scope_actor()\n  OR r.requester_id IS DISTINCT FROM scope_requester() OR r.agent_run_id IS DISTINCT FROM NEW.run_id\n  OR NEW.confirmed_by IS NOT NULL OR r.run_id IS NOT NULL OR r.confirmation_id IS NOT NULL\n  OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n     (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence link receipt mismatch' USING ERRCODE='23514'; END IF;\n IF NEW.origin='human' THEN\n  IF NEW.writer_id<>r.actor_id OR r.actor_id<>r.requester_id OR NEW.run_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals pr WHERE pr.tenant_id=NEW.tenant_id AND pr.id=NEW.writer_id AND pr.kind='human' AND pr.active) THEN\n   RAISE EXCEPTION 'evidence link human provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSIF NEW.origin='ai_draft' THEN\n  SELECT * INTO STRICT actual_link_run FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;\n  IF actual_link_run.category_id<>NEW.category_id OR actual_link_run.product_id IS DISTINCT FROM target_product OR actual_link_run.writer_id<>NEW.writer_id\n   OR actual_link_run.requester_id<>r.requester_id OR actual_link_run.writer_id<>r.actor_id OR actual_link_run.reverted_at IS NOT NULL OR actual_link_run.state='cancelled'\n   OR (target_proposal IS NOT NULL AND actual_link_run.proposal_id IS DISTINCT FROM target_proposal)\n   OR (target_proposal IS NULL AND actual_link_run.private_context)\n   OR NOT EXISTS(SELECT 1 FROM agent_tool_calls tc WHERE tc.tenant_id=NEW.tenant_id AND tc.run_id=NEW.run_id\n    AND tc.receipt_id=r.id AND tc.state='completed' AND tc.execution_binding->>'operation'=r.operation) THEN\n   RAISE EXCEPTION 'evidence link T0 provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'evidence link imported path unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  IF NOT EXISTS(SELECT 1 FROM proposal_revisions document_revision\n    JOIN action_receipts actual_receipt ON actual_receipt.tenant_id=document_revision.tenant_id AND actual_receipt.id=document_revision.receipt_id\n    JOIN proposals current_proposal ON current_proposal.tenant_id=document_revision.tenant_id AND current_proposal.id=document_revision.proposal_id\n    JOIN evidence_links actual_link ON actual_link.tenant_id=actual_receipt.tenant_id AND actual_link.id=actual_receipt.subject_id\n    WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.category_id=NEW.category_id\n     AND document_revision.proposal_id=p.id AND document_revision.receipt_id=r.id\n     AND document_revision.revision=current_proposal.revision AND document_revision.changed_items='[]'::jsonb\n     AND document_revision.actor_id=r.actor_id AND document_revision.run_id IS NOT DISTINCT FROM r.agent_run_id\n     AND actual_link.id=NEW.id AND actual_link.receipt_id=r.id\n     AND document_revision.xmin=actual_receipt.xmin AND current_proposal.xmin=actual_receipt.xmin AND actual_link.xmin=actual_receipt.xmin\n     AND EXISTS(SELECT 1 FROM proposal_revisions prior WHERE prior.tenant_id=document_revision.tenant_id\n      AND prior.proposal_id=document_revision.proposal_id AND prior.revision=document_revision.revision-1))\n   OR (SELECT count(*) FROM proposal_revisions document_revision WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.receipt_id=r.id)<>1\n   OR p.private_source_count<>(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private')\n   OR p.effective_visibility IS DISTINCT FROM (CASE WHEN p.private_source_count>0 THEN 'private' ELSE p.visibility END)\n   OR EXISTS((SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id)\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id)\n     UNION ALL (SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id))) THEN\n   RAISE EXCEPTION 'evidence link missing proposal revision or projection' USING ERRCODE='23514'; END IF;\n END IF;\n RETURN NULL;\nEND $function$\n"

CONFIRMATION_GUARD = "CREATE OR REPLACE FUNCTION public.m3_material_confirmation_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE old_material boolean=false; new_material boolean=false;\nBEGIN\n IF TG_OP<>'INSERT' THEN\n  old_material=OLD.operation IN ('category.knowledge.add','category.knowledge.withdraw',\n   'category.knowledge.promote','category.parameter.publish','evidence.claim.record','evidence.claim.withdraw','proposal.share','ai.run.revert','product.definition.item.patch');\n END IF;\n IF TG_OP<>'DELETE' THEN\n  new_material=NEW.operation IN ('category.knowledge.add','category.knowledge.withdraw',\n   'category.knowledge.promote','category.parameter.publish','evidence.claim.record','evidence.claim.withdraw','proposal.share','ai.run.revert','product.definition.item.patch');\n END IF;\n IF old_material OR new_material THEN\n  IF TG_OP='DELETE' THEN\n   RAISE EXCEPTION 'material confirmation must be retained' USING ERRCODE='23514';\n  ELSIF TG_OP='INSERT' THEN\n   IF NEW.consumed IS DISTINCT FROM false THEN\n    RAISE EXCEPTION 'material confirmation starts unconsumed' USING ERRCODE='23514';\n   END IF;\n  ELSIF OLD.consumed IS DISTINCT FROM false OR NEW.consumed IS DISTINCT FROM true\n   OR (to_jsonb(NEW)-'consumed') IS DISTINCT FROM (to_jsonb(OLD)-'consumed') THEN\n   RAISE EXCEPTION 'material confirmation can only be consumed once' USING ERRCODE='23514';\n  END IF;\n END IF;\n IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n RETURN NEW;\nEND $function$\n"

SOURCES_VALID = "CREATE OR REPLACE FUNCTION public.m3_definition_item_sources_valid(t uuid, c uuid, pid uuid, seeds jsonb, shared boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE refs jsonb; ref jsonb; sid uuid; source_ver integer; valid boolean; body text;\nBEGIN\n IF category_access(t,c,true) IS DISTINCT FROM true THEN RETURN false; END IF;\n refs=m3_reference_graph(t,c,seeds);\n IF refs IS NULL THEN RETURN false; END IF;\n -- Claims are locked once in UUID order, before their source roots. All reads\n -- remain actual scope/audience checks below; no body leaves this function.\n PERFORM 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='claim') ORDER BY claim.id FOR SHARE;\n PERFORM 1 FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.category_id=c AND artifact.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original')) ORDER BY artifact.id FOR SHARE;\n PERFORM 1 FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c AND snapshot.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='snapshot') ORDER BY snapshot.id FOR SHARE;\n PERFORM 1 FROM definition_revisions definition WHERE definition.tenant_id=t AND definition.category_id=c AND definition.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='definition') ORDER BY definition.id FOR SHARE;\n PERFORM 1 FROM products model WHERE model.tenant_id=t AND model.category_id=c AND model.id IN\n  (SELECT definition.product_id FROM definition_revisions definition WHERE definition.tenant_id=t AND definition.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='definition')\n   UNION SELECT artifact.product_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY model.id FOR SHARE;\n PERFORM 1 FROM uploaded_originals original WHERE original.tenant_id=t AND original.category_id=c AND original.id IN\n  (SELECT artifact.original_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY original.id FOR SHARE;\n PERFORM 1 FROM original_security security WHERE security.tenant_id=t AND security.category_id=c AND security.original_id IN\n  (SELECT artifact.original_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY security.id FOR SHARE;\n IF refs IS DISTINCT FROM m3_reference_graph(t,c,seeds) THEN RETURN false; END IF;\n FOR ref IN SELECT item FROM jsonb_array_elements(refs) item LOOP\n  sid=(ref->>'id')::uuid; source_ver=(ref->>'version')::integer; valid=false; body=NULL;\n  IF ref->>'type'='definition' THEN\n   SELECT EXISTS(SELECT 1 FROM definition_revisions definition JOIN products model\n    ON model.tenant_id=definition.tenant_id AND model.category_id=definition.category_id AND model.id=definition.product_id\n    WHERE definition.tenant_id=t AND definition.category_id=c AND definition.id=sid AND definition.revision=source_ver\n     AND (definition.status<>'published' OR m3_published_baseline(t,c,model.id,definition.id,definition.revision))\n     AND source_object_audience(t,c,'definition_revisions',definition.id,definition.owner_id,definition.visibility)\n     AND source_object_audience(t,c,'products',model.id,model.owner_id,model.visibility)) INTO valid;\n  ELSIF ref->>'type' IN ('artifact','original') THEN\n   SELECT artifact.content INTO body FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.category_id=c\n    AND artifact.id=sid AND artifact.revision=source_ver AND artifact.status='active' AND m3_evidence_source_reader(t,c,'artifact',sid)\n    AND (artifact.original_id IS NULL OR EXISTS(SELECT 1 FROM original_security security WHERE security.tenant_id=t\n     AND security.category_id=c AND security.original_id=artifact.original_id AND security.source_state='active' AND security.disposition='active'));\n   valid=FOUND;\n  ELSIF ref->>'type'='snapshot' THEN\n   SELECT snapshot.markdown INTO body FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c\n    AND snapshot.id=sid AND source_ver=1 AND snapshot.status IN ('ok','partial') AND m3_evidence_source_reader(t,c,'snapshot',sid);\n   valid=FOUND;\n  ELSIF ref->>'type'='claim' THEN\n   SELECT EXISTS(SELECT 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=sid\n    AND claim.revision=source_ver AND claim.status='active' AND m3_claim_reader(t,c,sid)\n    AND (ref->>'line' IS NULL OR (ref->>'line')::integer=claim.line)\n    AND (ref->>'quote' IS NULL OR position(ref->>'quote' IN claim.quote)>0)) INTO valid;\n  ELSIF ref->>'type'='knowledge' THEN\n   SELECT EXISTS(SELECT 1 FROM category_knowledge_entries knowledge WHERE knowledge.tenant_id=t AND knowledge.category_id=c\n    AND knowledge.id=sid AND knowledge.version=source_ver AND knowledge.action<>'withdraw') INTO valid;\n  ELSIF ref->>'type'='parameter' THEN\n   SELECT EXISTS(SELECT 1 FROM parameter_versions parameter WHERE parameter.tenant_id=t AND parameter.category_id=c\n    AND parameter.parameter_id=sid AND parameter.version=source_ver) INTO valid;\n  ELSIF ref->>'type'='human' THEN\n   SELECT EXISTS(SELECT 1 FROM principals person WHERE person.tenant_id=t AND person.id=sid AND person.active AND person.kind='human'\n    AND nullif(ref->>'statement','') IS NOT NULL) INTO valid;\n  END IF;\n  IF ref->>'type' IN ('artifact','original') THEN\n   valid=valid AND direct_source_set_visible(t,c,pid,jsonb_build_array(jsonb_build_object('artifact_id',sid,'expected_revision',source_ver)));\n   IF shared THEN valid=valid AND EXISTS(SELECT 1 FROM artifact_versions a WHERE a.tenant_id=t AND a.category_id=c AND a.id=sid AND a.visibility='category'\n    AND (a.original_id IS NULL OR EXISTS(SELECT 1 FROM uploaded_originals o WHERE o.tenant_id=t AND o.category_id=c AND o.id=a.original_id AND o.visibility='category'))\n    AND (a.product_id IS NULL OR EXISTS(SELECT 1 FROM products p WHERE p.tenant_id=t AND p.id=a.product_id AND p.visibility='category'))); END IF;\n  ELSIF shared AND ref->>'type'='claim' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=sid AND claim.privacy='shared');\n  ELSIF shared AND ref->>'type'='snapshot' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c AND snapshot.id=sid AND snapshot.visibility='category');\n  ELSIF shared AND ref->>'type'='definition' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM definition_revisions d JOIN products p ON p.tenant_id=d.tenant_id AND p.id=d.product_id\n    WHERE d.tenant_id=t AND d.category_id=c AND d.id=sid AND d.visibility='category' AND p.visibility='category');\n  END IF;\n  IF valid IS DISTINCT FROM true THEN RETURN false; END IF;\n  IF body IS NOT NULL AND (ref->>'line' IS NOT NULL OR ref->>'quote' IS NOT NULL) THEN\n   IF ref->>'line' IS NULL OR ref->>'quote' IS NULL OR (ref->>'line')::integer<1\n    OR position(ref->>'quote' IN split_part(replace(body,E'\\r\\n',E'\\n'),E'\\n',(ref->>'line')::integer))=0 THEN RETURN false; END IF;\n  END IF;\n END LOOP;\n RETURN true;\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN false;\nEND $function$\n"

ITEM_INSERT = """
CREATE FUNCTION public.m3_definition_item_insert()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
DECLARE prior definition_spec_current; parent definition_revisions; bound_category uuid;
BEGIN
 -- This trigger sorts before the predecessor a_published_definition_child,
 -- which already locks the Definition. Resolve identity without reading body,
 -- then acquire the same Category -> Product -> Definition fence as commands.
 SELECT category_id INTO STRICT bound_category FROM products WHERE tenant_id=NEW.tenant_id AND id=NEW.product_id;
 IF NEW.category_id IS NOT NULL AND NEW.category_id IS DISTINCT FROM bound_category THEN
  RAISE EXCEPTION 'definition item category mismatch' USING ERRCODE='23514'; END IF;
 NEW.category_id=bound_category;
 PERFORM 1 FROM categories WHERE tenant_id=NEW.tenant_id AND id=bound_category FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'definition item category unavailable' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM products WHERE tenant_id=NEW.tenant_id AND category_id=bound_category AND id=NEW.product_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'definition item product unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT parent FROM definition_revisions WHERE tenant_id=NEW.tenant_id
  AND category_id=NEW.category_id AND product_id=NEW.product_id AND id=NEW.definition_id FOR UPDATE;
 IF parent.sealed OR parent.status<>'draft' THEN RAISE EXCEPTION 'definition is fixed' USING ERRCODE='23514'; END IF;
 NEW.item_id=coalesce(NEW.item_id,NEW.id); NEW.item_version=coalesce(NEW.item_version,1); NEW.removed=coalesce(NEW.removed,false);
 SELECT * INTO prior FROM definition_spec_current WHERE tenant_id=NEW.tenant_id AND item_id=NEW.item_id FOR UPDATE;
 IF FOUND THEN
  IF ROW(prior.category_id,prior.product_id,prior.definition_id,prior.key) IS DISTINCT FROM
    ROW(NEW.category_id,NEW.product_id,NEW.definition_id,NEW.key) OR NEW.item_version<>prior.current_version+1 THEN
   RAISE EXCEPTION 'definition item scope or predecessor mismatch' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.item_id IS DISTINCT FROM NEW.id OR NEW.item_version<>1 OR NEW.removed THEN
   RAISE EXCEPTION 'definition item must start at its original row' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$
"""

ITEM_CURRENT = """
CREATE FUNCTION public.m3_definition_item_current()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
BEGIN
 INSERT INTO definition_spec_current(id,tenant_id,category_id,product_id,definition_id,item_id,
  current_row_id,current_version,key,removed,created_at)
 VALUES(NEW.item_id,NEW.tenant_id,NEW.category_id,NEW.product_id,NEW.definition_id,NEW.item_id,
  NEW.id,NEW.item_version,NEW.key,NEW.removed,NEW.created_at)
 ON CONFLICT(tenant_id,item_id) DO UPDATE SET current_row_id=EXCLUDED.current_row_id,
  current_version=EXCLUDED.current_version,removed=EXCLUDED.removed
 WHERE definition_spec_current.category_id=NEW.category_id AND definition_spec_current.product_id=NEW.product_id
  AND definition_spec_current.definition_id=NEW.definition_id AND definition_spec_current.key=NEW.key
  AND definition_spec_current.current_version=NEW.item_version-1;
 IF NOT FOUND THEN RAISE EXCEPTION 'definition item projection moved' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$
"""

FIXED_CONSUMED = """
CREATE FUNCTION public.m3_definition_fixed_consumed(t uuid,c uuid,d uuid,ver integer)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
DECLARE table_name text; doc jsonb; vars jsonb=jsonb_build_object('id',d::text,'version',ver);
BEGIN
 IF EXISTS(SELECT 1 FROM proposals p WHERE p.tenant_id=t AND p.category_id=c AND p.baseline_definition_id=d AND p.baseline_definition_revision=ver)
  OR EXISTS(SELECT 1 FROM definition_revisions x WHERE x.tenant_id=t AND x.category_id=c AND x.id<>d
   AND (x.parent_definition_id=d OR (x.derived_from_definition_id=d AND x.derived_from_definition_revision=ver)))
  OR EXISTS(SELECT 1 FROM variant_revisions x WHERE x.tenant_id=t AND x.category_id=c
   AND ((x.parent_definition_id=d AND x.parent_revision=ver) OR x.definition_id=d
    OR (x.effective_definition->>'definition_id'=d::text AND x.effective_definition->'definition_revision'=to_jsonb(ver))))
  OR EXISTS(SELECT 1 FROM project_product_links x WHERE x.tenant_id=t AND x.category_id=c AND x.definition_id=d AND x.definition_revision=ver)
  OR EXISTS(SELECT 1 FROM engineering_configurations x WHERE x.tenant_id=t AND x.category_id=c AND x.definition_id=d AND x.definition_revision=ver)
  OR EXISTS(SELECT 1 FROM proposal_sources x WHERE x.tenant_id=t AND x.category_id=c AND x.source_type='definition' AND x.source_id=d AND x.source_version=ver)
 THEN RETURN true; END IF;
 -- Real persisted business reference containers only. Transport and ordinary
 -- comparison Calls alone do not capture an immutable baseline.
 FOREACH table_name IN ARRAY ARRAY['proposals','proposal_item_versions','proposal_submissions',
  'category_knowledge_entries','definition_specs'] LOOP
  FOR doc IN EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE tenant_id=$1 AND category_id=$2',table_name) USING t,c LOOP
   IF table_name='definition_specs' AND doc->>'definition_id'=d::text THEN CONTINUE; END IF;
   IF jsonb_path_exists(jsonb_build_array(doc->'source_refs',doc->'context_refs',doc->'content',doc->'frozen_document'),
    '$.** ? (@.type == "definition" && @.id == $id && @.version == $version)',vars,true) THEN RETURN true; END IF;
  END LOOP;
 END LOOP;
 RETURN EXISTS(SELECT 1 FROM claims claim JOIN agent_tool_calls call ON call.tenant_id=claim.tenant_id
  AND call.id=(claim.extraction_ref->>'call_id')::uuid AND call.run_id=claim.run_id
  JOIN agent_tool_calls model ON model.tenant_id=call.tenant_id AND model.run_id=call.run_id
   AND model.id=(call.execution_binding->>'model_call_id')::uuid
  WHERE claim.tenant_id=t AND claim.category_id=c AND claim.nature='computed'
   AND call.state='completed' AND call.execution_binding->>'kind'='read'
   AND call.execution_binding->>'read_kind'='compute/v1' AND model.state='completed'
   AND model.execution_binding->>'kind'='model' AND model.execution_binding->>'isolation'='main'
   AND jsonb_path_exists(model.result->'calls'->((call.execution_binding->>'response_index')::integer)->'arguments',
    '$.** ? (@.type == "definition" && @.id == $id && @.version == $version)',vars,true));
END $function$
"""

FIXED_VISIBLE = """
CREATE FUNCTION public.m3_definition_fixed_consumed_visible(t uuid,c uuid,d uuid,ver integer)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
BEGIN
 IF category_access(t,c) IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM definition_revisions x
  JOIN products p ON p.tenant_id=x.tenant_id AND p.category_id=x.category_id AND p.id=x.product_id
  WHERE x.tenant_id=t AND x.category_id=c AND x.id=d AND x.revision=ver
   AND source_object_audience(t,c,'products',p.id,p.owner_id,p.visibility)
   AND source_object_audience(t,c,'definition_revisions',x.id,x.owner_id,x.visibility)
   AND definition_sources_visible(t,c,p.id,x.id)) THEN RETURN NULL; END IF;
 RETURN m3_definition_fixed_consumed(t,c,d,ver);
END $function$
"""

CONTENT = """
CREATE FUNCTION public.m3_definition_item_content(value jsonb,refs jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
 SELECT to_jsonb(x)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at',
  'item_id','item_version','removed','prepared_candidate_id','origin','writer_id','run_id','confirmed_by','receipt_id']
 FROM jsonb_populate_record(NULL::definition_specs,
  '{"parameter_id":null,"parameter_version":null,"value":null,"lower":null,"upper":null,"text":null,"unit":null,
    "tolerance":null,"test_conditions":[],"method":null,"acceptance_criterion":null,"nature":"decided",
    "state":"proposed","owner_id":null,"reason":"","item_status":"unknown","condition_note":null,
    "modality":null,"exceptions":[],"applicable_variants":[],"availability":"unknown"}'::jsonb || value ||
   jsonb_build_object('text',value->'text_value','method',value->'verification_method',
    'reason',coalesce(value->>'reason',''),'source_refs',(SELECT coalesce(jsonb_agg('{"line":null,"quote":null,"statement":null}'::jsonb||ref ORDER BY n),'[]') FROM jsonb_array_elements(coalesce(refs,'[]')) WITH ORDINALITY x(ref,n)),
    'state',CASE WHEN value->>'item_status'='expert_pending' THEN 'needs_confirmation' ELSE 'proposed' END)) x
$function$
"""

ITEM_ATOM = """
CREATE FUNCTION public.m3_definition_item_atom()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
DECLARE item definition_specs; prior definition_specs; baseline definition_specs; parent definition_revisions;
 receipt action_receipts; actual_run agent_runs; candidate proposal_prepared_candidates; confirmation confirmations;
 call agent_tool_calls; model agent_tool_calls; rx xid; ix xid; payload jsonb; operation jsonb; manifest jsonb;
 business jsonb; expected jsonb; first_version integer; last_version integer; actual_count integer;
 excluded text[]=ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at',
  'item_id','item_version','removed','prepared_candidate_id','origin','writer_id','run_id','confirmed_by','receipt_id'];
BEGIN
 SELECT * INTO STRICT item FROM definition_specs WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 SELECT * INTO STRICT parent FROM definition_revisions WHERE tenant_id=item.tenant_id AND category_id=item.category_id
  AND product_id=item.product_id AND id=item.definition_id FOR UPDATE;
 SELECT xmin INTO ix FROM definition_specs WHERE tenant_id=item.tenant_id AND id=item.id;
 IF NOT EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=item.tenant_id
  AND current.category_id=item.category_id AND current.product_id=item.product_id AND current.definition_id=item.definition_id
  AND current.item_id=item.item_id AND current.current_version=(SELECT max(s.item_version) FROM definition_specs s
   WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id)) THEN
  RAISE EXCEPTION 'definition item missing exact latest projection' USING ERRCODE='23514'; END IF;
 IF item.receipt_id IS NULL THEN
  SELECT * INTO STRICT receipt FROM action_receipts r WHERE r.tenant_id=item.tenant_id AND r.category_id=item.category_id
   AND r.product_id=item.product_id AND r.subject_type='definition_revision' AND r.subject_id=parent.id
   AND r.subject_revision=parent.revision AND r.operation='product.definition.draft' AND r.xmin=ix;
 ELSE SELECT * INTO STRICT receipt FROM action_receipts WHERE tenant_id=item.tenant_id AND id=item.receipt_id; END IF;
 SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=item.tenant_id AND id=receipt.id;
 IF rx IS DISTINCT FROM ix OR receipt.category_id IS DISTINCT FROM item.category_id
  OR receipt.actor_id IS DISTINCT FROM scope_actor() OR receipt.requester_id IS DISTINCT FROM scope_requester()
  OR receipt.run_id IS NOT NULL THEN RAISE EXCEPTION 'definition item receipt identity mismatch' USING ERRCODE='23514'; END IF;
 -- Existing native/G0 assembly remains one immutable initial snapshot.
 IF receipt.operation IN ('product.definition.draft','proposal.g0.decide') THEN
  IF item.item_id<>item.id OR item.item_version<>1 OR item.removed
   OR ix IS DISTINCT FROM (SELECT xmin FROM definition_revisions WHERE tenant_id=item.tenant_id AND id=parent.id) THEN
   RAISE EXCEPTION 'initial definition item is not part of creation' USING ERRCODE='23514'; END IF;
  IF receipt.operation='proposal.g0.decide' THEN
   IF parent.g0_decision_id IS NULL THEN RAISE EXCEPTION 'initial G0 item lacks decision' USING ERRCODE='23514'; END IF;
   PERFORM m3_g0_derivation_assert(item.tenant_id,item.category_id,parent.g0_decision_id);
  ELSE
   IF receipt.product_id IS DISTINCT FROM item.product_id OR receipt.subject_type<>'definition_revision'
    OR receipt.subject_id<>parent.id OR receipt.subject_revision<>parent.revision OR receipt.agent_run_id IS NOT NULL
    OR receipt.actor_id<>receipt.requester_id OR parent.sealed OR parent.status<>'draft'
    OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=receipt.actor_id AND p.kind='human' AND p.active) THEN
    RAISE EXCEPTION 'native definition item creation receipt mismatch' USING ERRCODE='23514'; END IF;
   IF item.origin<>'human' OR item.run_id IS NOT NULL OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL
    OR (item.writer_id IS NOT NULL AND item.writer_id<>receipt.actor_id) THEN
    IF parent.parent_definition_id IS NULL OR NOT EXISTS(SELECT 1 FROM definition_specs previous
     JOIN definition_spec_current current ON current.tenant_id=previous.tenant_id AND current.current_row_id=previous.id AND NOT current.removed
     WHERE previous.tenant_id=item.tenant_id AND previous.category_id=item.category_id AND previous.product_id=item.product_id
      AND previous.definition_id=parent.parent_definition_id
      AND (to_jsonb(previous)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id'])
       IS NOT DISTINCT FROM (to_jsonb(item)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id'])) THEN
     RAISE EXCEPTION 'native continuation lost original provenance' USING ERRCODE='23514'; END IF;
   END IF;
   IF m3_definition_item_sources_valid(item.tenant_id,item.category_id,item.product_id,item.source_refs,parent.visibility='category') IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'native continuation item sources unavailable' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NULL;
 END IF;
 IF parent.sealed OR parent.status<>'draft' OR receipt.product_id IS DISTINCT FROM item.product_id
  OR m3_definition_fixed_consumed(item.tenant_id,item.category_id,parent.id,parent.revision) THEN
  RAISE EXCEPTION 'fixed definition requires continuation' USING ERRCODE='23514'; END IF;
 SELECT * INTO prior FROM definition_specs WHERE tenant_id=item.tenant_id AND item_id=item.item_id AND item_version=item.item_version-1;
 business=to_jsonb(item)-excluded;
 SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',s.item_id,'item_version',s.item_version,'row_id',s.id,'key',s.key,'removed',s.removed)
  ORDER BY s.id),'[]') INTO manifest FROM definition_specs s WHERE s.tenant_id=item.tenant_id AND s.receipt_id=receipt.id;
 IF jsonb_typeof(receipt.result->(CASE WHEN receipt.operation='ai.run.revert' THEN 'definition_item_changes' ELSE 'changes' END)) IS DISTINCT FROM 'array'
  OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(receipt.result->(CASE WHEN receipt.operation='ai.run.revert' THEN 'definition_item_changes' ELSE 'changes' END))) IS DISTINCT FROM manifest THEN
  RAISE EXCEPTION 'definition item receipt manifest mismatch' USING ERRCODE='23514'; END IF;
 IF receipt.operation='ai.run.revert' THEN
  SELECT * INTO STRICT actual_run FROM agent_runs WHERE tenant_id=item.tenant_id AND id=receipt.subject_id;
  PERFORM m3_evidence_revert_confirmation(item.tenant_id,item.category_id,receipt.id);
  IF receipt.subject_type<>'agent_run' OR actual_run.revert_receipt_id IS DISTINCT FROM receipt.id
   OR actual_run.requester_id IS DISTINCT FROM receipt.requester_id OR actual_run.product_id IS DISTINCT FROM item.product_id
   OR actual_run.category_id IS DISTINCT FROM item.category_id OR receipt.actor_id<>receipt.requester_id
   OR receipt.agent_run_id IS NOT NULL
   OR prior.run_id IS DISTINCT FROM actual_run.id OR prior.origin<>'ai_draft'
   OR prior.confirmed_by IS NOT NULL OR prior.item_status='confirmed' THEN
   RAISE EXCEPTION 'definition item compensation identity mismatch' USING ERRCODE='23514'; END IF;
  SELECT min(s.item_version),max(s.item_version),count(*) INTO first_version,last_version,actual_count FROM definition_specs s
   JOIN action_receipts r ON r.tenant_id=s.tenant_id AND r.id=s.receipt_id AND r.operation='product.definition.item.patch' AND r.agent_run_id=actual_run.id
   WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id AND s.run_id=actual_run.id;
  IF last_version IS DISTINCT FROM item.item_version-1 OR actual_count IS DISTINCT FROM last_version-first_version+1
   OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id
    AND s.item_version BETWEEN first_version AND last_version AND (s.confirmed_by IS NOT NULL OR s.item_status='confirmed' OR s.origin<>'ai_draft' OR s.writer_id IS DISTINCT FROM actual_run.writer_id)) THEN
   RAISE EXCEPTION 'definition item compensation lost contiguous run history' USING ERRCODE='23514'; END IF;
  IF first_version=1 THEN expected=to_jsonb(prior)-excluded;
   IF item.origin<>'human' OR item.writer_id IS DISTINCT FROM receipt.actor_id OR item.run_id IS NOT NULL
    OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL THEN
    RAISE EXCEPTION 'new item compensation must retain actual human actor' USING ERRCODE='23514'; END IF;
   IF NOT item.removed THEN RAISE EXCEPTION 'new run item compensation requires tombstone' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT * INTO STRICT baseline FROM definition_specs WHERE tenant_id=item.tenant_id AND item_id=item.item_id AND item_version=first_version-1;
   expected=to_jsonb(baseline)-excluded;
   IF ROW(item.origin,item.writer_id,item.run_id,item.confirmed_by,item.prepared_candidate_id)
    IS DISTINCT FROM ROW(baseline.origin,baseline.writer_id,baseline.run_id,baseline.confirmed_by,baseline.prepared_candidate_id) THEN
    RAISE EXCEPTION 'compensation must retain original value provenance' USING ERRCODE='23514'; END IF;
   IF item.removed IS DISTINCT FROM baseline.removed THEN RAISE EXCEPTION 'compensation removed state mismatch' USING ERRCODE='23514'; END IF;
  END IF;
  IF business IS DISTINCT FROM expected THEN RAISE EXCEPTION 'compensation must restore exact prior values' USING ERRCODE='23514'; END IF;
  RETURN NULL;
 END IF;
 IF receipt.operation<>'product.definition.item.patch' OR receipt.subject_type<>'definition_revision'
  OR receipt.subject_id<>parent.id OR receipt.subject_revision<>parent.revision THEN
  RAISE EXCEPTION 'definition patch receipt subject mismatch' USING ERRCODE='23514'; END IF;
 IF item.origin='human' THEN
  IF item.writer_id IS DISTINCT FROM receipt.actor_id OR receipt.actor_id<>receipt.requester_id
   OR item.run_id IS NOT NULL OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL
   OR receipt.agent_run_id IS NOT NULL OR receipt.confirmation_id IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=item.writer_id AND p.kind='human' AND p.active) THEN
   RAISE EXCEPTION 'definition human provenance mismatch' USING ERRCODE='23514'; END IF;
 ELSIF item.origin='ai_draft' THEN
  SELECT * INTO STRICT actual_run FROM agent_runs WHERE tenant_id=item.tenant_id AND id=item.run_id;
  IF actual_run.category_id IS DISTINCT FROM item.category_id OR actual_run.product_id IS DISTINCT FROM item.product_id
   OR actual_run.requester_id IS DISTINCT FROM receipt.requester_id OR actual_run.writer_id IS DISTINCT FROM item.writer_id
   OR actual_run.state='cancelled' OR actual_run.reverted_at IS NOT NULL
   OR (actual_run.private_context AND parent.visibility='category')
   OR (NOT item.removed AND item.item_status='confirmed')
   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=item.writer_id AND p.kind='agent' AND p.active) THEN
   RAISE EXCEPTION 'definition AI run provenance mismatch' USING ERRCODE='23514'; END IF;
  IF item.confirmed_by IS NULL THEN
   IF receipt.actor_id IS DISTINCT FROM item.writer_id OR receipt.agent_run_id IS DISTINCT FROM item.run_id
    OR receipt.confirmation_id IS NOT NULL OR item.prepared_candidate_id IS NOT NULL
    OR (prior.id IS NOT NULL AND (prior.origin='human' OR prior.confirmed_by IS NOT NULL OR prior.item_status='confirmed')) THEN
    RAISE EXCEPTION 'definition T0 cannot change human values' USING ERRCODE='23514'; END IF;
   SELECT * INTO STRICT call FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id AND receipt_id=receipt.id AND state='completed';
   IF call.execution_binding->>'kind' IS DISTINCT FROM 'domain_t0' OR call.execution_binding->>'operation' IS DISTINCT FROM receipt.operation
    OR (call.execution_binding->>'cancel_epoch')::integer IS DISTINCT FROM actual_run.cancel_epoch THEN
    RAISE EXCEPTION 'definition T0 lacks actual completed command' USING ERRCODE='23514'; END IF;
   SELECT * INTO STRICT model FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id
    AND id=(call.execution_binding->>'model_call_id')::uuid AND state='completed';
   IF model.execution_binding->>'kind' IS DISTINCT FROM 'model' OR model.execution_binding->>'isolation' IS DISTINCT FROM 'main'
    OR model.execution_binding->>'model_version' IS DISTINCT FROM actual_run.versions->>'model_version'
    OR model.execution_binding->>'model_route_digest' IS DISTINCT FROM actual_run.versions->>'model_route_digest'
    OR model.execution_binding->>'tool_definitions_digest' IS DISTINCT FROM actual_run.versions->'tool_definitions'->>'main'
    OR model.execution_binding->>'prompt_digest' IS DISTINCT FROM actual_run.versions->'prompt_prefixes'->>'main'
    OR model.execution_binding->>'cancel_epoch' IS DISTINCT FROM actual_run.cancel_epoch::text
    OR ((model.execution_binding->'loaded_skills') @> jsonb_build_array(call.execution_binding->'skill')) IS DISTINCT FROM true
    OR model.result->'calls'->((call.execution_binding->>'response_index')::integer)->>'name' IS DISTINCT FROM receipt.operation
    OR call.tool IS DISTINCT FROM receipt.operation
    OR NOT EXISTS(SELECT 1 FROM agent_run_events event WHERE event.tenant_id=item.tenant_id AND event.run_id=item.run_id
     AND event.id=(call.execution_binding->'skill'->>'load_event_id')::uuid AND event.body->>'type'='skill_loaded'
     AND event.body->>'key'=call.execution_binding->'skill'->>'key'
     AND event.body->>'version'=call.execution_binding->'skill'->>'version'
     AND event.body->>'digest'=call.execution_binding->'skill'->>'digest' AND event.body->>'isolation'='main') THEN
    RAISE EXCEPTION 'definition T0 model or actual skill mismatch' USING ERRCODE='23514'; END IF;
   PERFORM 1 FROM tenant_skill_enablements enablement WHERE enablement.tenant_id=item.tenant_id
    AND enablement.skill_key=call.execution_binding->'skill'->>'key' AND enablement.enabled AND enablement.pilot
    AND NOT enablement.qualification_revoked AND enablement.qualified_skill_version=call.execution_binding->'skill'->>'version'
    AND enablement.qualified_model_version=model.execution_binding->>'model_version'
    AND enablement.reviewed_by IS NOT NULL AND enablement.reviewed_at IS NOT NULL
    AND (SELECT count(DISTINCT value) FROM jsonb_array_elements(enablement.review_case_refs))>=10 FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'definition T0 qualification unavailable' USING ERRCODE='23514'; END IF;
   payload=model.result->'calls'->((call.execution_binding->>'response_index')::integer)->'arguments';
  ELSE
   SELECT * INTO STRICT candidate FROM proposal_prepared_candidates WHERE tenant_id=item.tenant_id AND id=item.prepared_candidate_id;
   SELECT * INTO STRICT confirmation FROM confirmations WHERE tenant_id=item.tenant_id AND id=receipt.confirmation_id;
   IF item.confirmed_by IS DISTINCT FROM receipt.actor_id OR receipt.actor_id<>receipt.requester_id
    OR receipt.agent_run_id IS DISTINCT FROM item.run_id OR candidate.category_id<>item.category_id
    OR candidate.run_id<>item.run_id OR candidate.writer_id<>item.writer_id OR candidate.requester_id<>receipt.requester_id
    OR candidate.operation<>receipt.operation OR (candidate.execution_binding->'model'->>'cancel_epoch')::integer IS DISTINCT FROM actual_run.cancel_epoch
    OR confirmation.consumed IS DISTINCT FROM true OR confirmation.actor_id<>receipt.actor_id
    OR confirmation.category_id<>item.category_id OR confirmation.product_id IS DISTINCT FROM item.product_id
    OR confirmation.operation<>receipt.operation OR confirmation.subject_type<>'definition_revision'
    OR confirmation.subject_id<>parent.id OR confirmation.revision<>parent.revision
    OR (SELECT xmin FROM confirmations WHERE tenant_id=item.tenant_id AND id=confirmation.id) IS DISTINCT FROM rx
    OR confirmation.snapshot->'payload'->>'prepared_by_run_id' IS DISTINCT FROM item.run_id::text
    OR confirmation.snapshot->'payload'->>'candidate_digest' IS DISTINCT FROM candidate.candidate_digest
    OR ((confirmation.snapshot->'payload')-ARRAY['prepared_by_run_id','candidate_digest','confirmation_token']) IS DISTINCT FROM candidate.payload THEN
    RAISE EXCEPTION 'definition T1 candidate or consumed confirmation mismatch' USING ERRCODE='23514'; END IF;
   SELECT * INTO STRICT model FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id
    AND id=(candidate.execution_binding->>'model_call_id')::uuid AND state='completed';
   IF model.execution_binding IS DISTINCT FROM candidate.execution_binding->'model'
    OR model.execution_binding->>'kind' IS DISTINCT FROM 'model'
    OR model.execution_binding->>'isolation' IS DISTINCT FROM 'main'
    OR ((model.execution_binding->'loaded_skills') @> jsonb_build_array(candidate.execution_binding->'skill')) IS DISTINCT FROM true
    OR model.execution_binding->>'cancel_epoch' IS DISTINCT FROM actual_run.cancel_epoch::text
    OR NOT EXISTS(SELECT 1 FROM agent_run_events event WHERE event.tenant_id=item.tenant_id AND event.run_id=item.run_id
     AND event.id=(candidate.execution_binding->'skill'->>'load_event_id')::uuid AND event.body->>'type'='skill_loaded'
     AND event.body->>'key'=candidate.execution_binding->'skill'->>'key'
     AND event.body->>'version'=candidate.execution_binding->'skill'->>'version'
     AND event.body->>'digest'=candidate.execution_binding->'skill'->>'digest' AND event.body->>'isolation'='main')
    OR model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->>'name' IS DISTINCT FROM receipt.operation THEN
    RAISE EXCEPTION 'definition candidate lacks actual model and loaded skill' USING ERRCODE='23514'; END IF;
   payload=candidate.payload;
  END IF;
  IF payload->>'definition_id' IS DISTINCT FROM parent.id::text OR jsonb_typeof(payload->'ops') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'definition candidate payload scope mismatch' USING ERRCODE='23514'; END IF;
  IF jsonb_array_length(payload->'ops')<>(SELECT count(*) FROM definition_specs spec_row WHERE spec_row.tenant_id=item.tenant_id AND spec_row.receipt_id=receipt.id)
   OR (item.confirmed_by IS NOT NULL AND jsonb_array_length(model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->'ops')<>jsonb_array_length(payload->'ops')) THEN
   RAISE EXCEPTION 'definition candidate operation set differs from committed manifest' USING ERRCODE='23514'; END IF;
  SELECT op INTO STRICT operation FROM jsonb_array_elements(payload->'ops') op
   WHERE (item.item_version>1 AND op->>'item_id'=item.item_id::text AND op->'base_version'=to_jsonb(item.item_version-1))
    OR (item.item_version=1 AND op->>'item_id' IS NULL AND op->'content'->>'key'=item.key);
  IF item.confirmed_by IS NOT NULL THEN
   SELECT op INTO STRICT expected FROM jsonb_array_elements(model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->'ops') op
    WHERE (item.item_version>1 AND op->>'item_id'=item.item_id::text AND op->'base_version'=to_jsonb(item.item_version-1))
     OR (item.item_version=1 AND op->>'item_id' IS NULL AND op->'content'->>'key'=item.key);
   IF model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->>'definition_id' IS DISTINCT FROM parent.id::text
    OR coalesce(expected->>'op','upsert') IS DISTINCT FROM coalesce(operation->>'op','upsert')
    OR (NOT item.removed AND m3_definition_item_content(expected->'content',expected->'source_refs')
     IS DISTINCT FROM m3_definition_item_content(operation->'content',operation->'source_refs')) THEN
    RAISE EXCEPTION 'definition prepared candidate changed actual model values' USING ERRCODE='23514'; END IF;
  END IF;
  IF item.removed IS DISTINCT FROM (coalesce(operation->>'op','upsert')='remove') THEN
   RAISE EXCEPTION 'definition candidate action mismatch' USING ERRCODE='23514'; END IF;
  IF NOT item.removed AND business IS DISTINCT FROM m3_definition_item_content(operation->'content',operation->'source_refs') THEN
   RAISE EXCEPTION 'definition candidate content differs from actual model values' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'definition patch has unsupported origin' USING ERRCODE='23514'; END IF;
 IF item.removed THEN
  IF prior.id IS NULL OR prior.removed OR business IS DISTINCT FROM (to_jsonb(prior)-excluded) THEN
   RAISE EXCEPTION 'definition removal must retain complete previous values' USING ERRCODE='23514'; END IF;
  RETURN NULL;
 END IF;
 IF (item.parameter_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM parameter_versions pv WHERE pv.tenant_id=item.tenant_id
  AND pv.category_id=item.category_id AND pv.parameter_id=item.parameter_id AND pv.version=item.parameter_version
  AND pv.key=item.key AND pv.value_type=item.value_type AND pv.unit IS NOT DISTINCT FROM item.unit))
  OR (item.owner_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM principals p JOIN grants g ON g.tenant_id=p.tenant_id AND g.principal_id=p.id
   WHERE p.tenant_id=item.tenant_id AND p.id=item.owner_id AND p.kind='human' AND p.active AND g.category_id=item.category_id
    AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp())))
  OR (item.item_status='confirmed' AND (item.availability NOT IN ('known','not_applicable') OR jsonb_array_length(item.source_refs)=0))
  OR (item.availability='not_applicable' AND nullif(item.reason,'') IS NULL)
  OR (item.value_type='boolean' AND item.availability='known' AND item.text NOT IN ('true','false'))
  OR item.value::text IN ('NaN','Infinity','-Infinity') OR item.lower::text IN ('NaN','Infinity','-Infinity')
  OR item.upper::text IN ('NaN','Infinity','-Infinity') OR item.tolerance::text IN ('NaN','Infinity','-Infinity')
  OR m3_definition_item_sources_valid(item.tenant_id,item.category_id,item.product_id,item.source_refs,parent.visibility='category') IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'definition item dictionary, member or source proof mismatch' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$
"""

PREDECESSOR_SOURCE_CONSUMER = "CREATE OR REPLACE FUNCTION public.assert_category_source_consumer()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nBEGIN\n IF NOT EXISTS (SELECT 1 FROM public.artifact_versions a\n  WHERE a.tenant_id=NEW.tenant_id AND a.category_id=NEW.category_id\n    AND a.id=NEW.artifact_id AND (a.product_id IS NULL OR a.product_id=NEW.product_id))\n THEN\n  IF TG_TABLE_NAME='definition_sources' AND TG_OP='INSERT' THEN\n   IF public.m3_g0_product_source_proven(NEW.tenant_id,NEW.category_id,NEW.product_id,NEW.definition_id,\n    NEW.artifact_id,NEW.source_revision,NEW.line,NEW.quote,true) THEN RETURN NEW; END IF;\n  END IF;\n  RAISE EXCEPTION 'source consumer scope mismatch' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND $function$\n"

SOURCE_CONSUMER = "CREATE OR REPLACE FUNCTION public.assert_category_source_consumer()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nBEGIN\n IF NOT EXISTS (SELECT 1 FROM public.artifact_versions a\n  WHERE a.tenant_id=NEW.tenant_id AND a.category_id=NEW.category_id\n    AND a.id=NEW.artifact_id AND (a.product_id IS NULL OR a.product_id=NEW.product_id))\n THEN\n  IF TG_TABLE_NAME='definition_sources' AND TG_OP='INSERT' THEN\n   IF public.m3_g0_product_source_proven(NEW.tenant_id,NEW.category_id,NEW.product_id,NEW.definition_id,\n    NEW.artifact_id,NEW.source_revision,NEW.line,NEW.quote,true) OR public.m3_definition_inherited_source_proven(NEW.tenant_id,NEW.category_id,NEW.product_id,NEW.definition_id,NEW.artifact_id,NEW.source_revision,NEW.line,NEW.quote) THEN RETURN NEW; END IF;\n  END IF;\n  RAISE EXCEPTION 'source consumer scope mismatch' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND $function$\n"

INHERITED_SOURCE = """
CREATE FUNCTION public.m3_definition_inherited_source_proven(t uuid,c uuid,p uuid,d uuid,sid uuid,ver integer,line_no integer,quote_text text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
 SELECT category_access(t,c,true) AND EXISTS(SELECT 1 FROM definition_revisions child
  JOIN definition_revisions parent ON parent.tenant_id=child.tenant_id AND parent.category_id=child.category_id
   AND parent.product_id=child.product_id AND parent.id=child.parent_definition_id
  JOIN definition_sources source ON source.tenant_id=parent.tenant_id AND source.category_id=parent.category_id
   AND source.product_id=parent.product_id AND source.definition_id=parent.id
  JOIN artifact_versions artifact ON artifact.tenant_id=source.tenant_id AND artifact.category_id=source.category_id AND artifact.id=source.artifact_id
  WHERE child.tenant_id=t AND child.category_id=c AND child.product_id=p AND child.id=d
   AND child.status='draft' AND NOT child.sealed AND child.revision>parent.revision
   AND child.variant_id IS NOT DISTINCT FROM parent.variant_id
   AND source.artifact_id=sid AND source.source_revision=ver AND source.line=line_no AND source.quote=quote_text
   AND artifact.status='active' AND artifact.revision=ver
   AND source_object_audience(t,c,'definition_revisions',parent.id,parent.owner_id,parent.visibility)
   AND direct_source_set_visible(t,c,p,jsonb_build_array(jsonb_build_object('artifact_id',sid,'expected_revision',ver))))
$function$
"""

RECEIPT_ATOM = """
CREATE FUNCTION public.m3_definition_item_receipt_atom()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
DECLARE actual_count integer; actual_manifest jsonb; rx xid;
BEGIN
 IF NEW.operation<>'product.definition.item.patch' THEN RETURN NULL; END IF;
 SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 SELECT count(*),coalesce(jsonb_agg(jsonb_build_object('item_id',s.item_id,'item_version',s.item_version,
  'row_id',s.id,'key',s.key,'removed',s.removed) ORDER BY s.id),'[]') INTO actual_count,actual_manifest
  FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=NEW.id;
 IF actual_count=0 OR NEW.subject_type<>'definition_revision'
  OR jsonb_typeof(NEW.result->'changes') IS DISTINCT FROM 'array'
  OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(NEW.result->'changes')) IS DISTINCT FROM actual_manifest
  OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=NEW.id
   AND (s.definition_id IS DISTINCT FROM NEW.subject_id OR s.product_id IS DISTINCT FROM NEW.product_id
    OR s.category_id IS DISTINCT FROM NEW.category_id OR s.xmin IS DISTINCT FROM rx)) THEN
  RAISE EXCEPTION 'definition patch receipt has no exact committed versions' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$
"""

