PREDECESSOR_REVERT_SUBJECTS_CONSUMED = "CREATE OR REPLACE FUNCTION public.revert_subjects_consumed(t uuid, c uuid, targets jsonb, own_receipts uuid[])\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE tables text[]=ARRAY['action_receipts','actual_configurations','artifact_versions','audit_entries','bom_lines','bom_revisions','build_authorization_decisions','build_current_authorizations','build_current_execution_assessments','build_execution_assessments','build_lots','build_operational_current','build_operational_facts','build_readiness','build_starts','builds','capa_current_observations','capa_current_verification_rules','capa_named_verification_reviews','capa_observation_facts','capa_remediation_links','capa_verification_evidence','capa_verification_rule_facts','change_approval_records','change_dependency_clocks','change_graph_captures','change_implementation_captures','change_implementation_records','change_order_records','change_request_currents','change_request_versions','claim_consumptions','claims','controlled_change_coverage_currents','controlled_change_coverage_facts','controlled_change_policy_currents','controlled_change_policy_facts','controlled_change_selection_currents','controlled_change_selection_facts','cost_current_inputs','cost_estimates','cost_input_snapshots','cost_source_captures','definition_revisions','definition_sources','definition_specs','engineering_configurations','manufacturing_baseline_document_links','manufacturing_preparation_currents','manufacturing_preparation_versions','measurement_import_captures','operational_material_holds','operational_resource_occupancies','original_scan_requests','original_scan_results','original_security','outbox_events','parts','plan_proposals','plan_revisions','process_revisions','product_variants','professional_authority_current','professional_authority_facts','project_product_links','project_tasks','project_work_packages','projects','quality_current_issues','quality_current_policies','quality_event_failure_links','quality_failure_maps','quality_issue_versions','quality_policy_facts','request_keys','runs','sample_allocations','sample_current_readiness','sample_readiness_facts','sample_run_usages','sample_units','sample_usage_sentinels','supply_current_snapshots','supply_kit_projections','supply_snapshots','supply_source_captures','task_dependencies','test_measurements','test_resource_current','test_resource_facts','test_resource_reservations','test_result_actions','test_result_projections','uploaded_originals','variant_revisions','verification_actual_method_applicabilities','verification_actual_method_batches','verification_current_actual_methods','verification_current_formal_requests','verification_current_preparations','verification_current_runs','verification_formal_requests','verification_handoff_facts','verification_launch_facts','verification_method_applicabilities','verification_preparations','verification_run_identities','verification_run_versions','verification_window_proposals','work_requests','proposals','proposal_item_versions','proposal_submissions','proposal_decisions','category_knowledge_entries','evidence_links']; table_name text; target jsonb; ids uuid[]='{}'; payload jsonb; bound_run_id uuid; rr action_receipts; ar agent_runs;\nBEGIN\n IF category_access(t,c,true) IS DISTINCT FROM true OR scope_actor() IS DISTINCT FROM scope_requester()\n  OR jsonb_typeof(targets) IS DISTINCT FROM 'array' OR own_receipts IS NULL THEN RETURN true; END IF;\n IF cardinality(own_receipts)=0 THEN RETURN jsonb_array_length(targets)<>0; END IF;\n IF cardinality(own_receipts)<>(SELECT count(DISTINCT v) FROM unnest(own_receipts) x(v))\n  OR cardinality(own_receipts)<>jsonb_array_length(targets)\n  OR jsonb_array_length(targets)<>(SELECT count(DISTINCT v->>'id') FROM jsonb_array_elements(targets) x(v)) THEN RETURN true; END IF;\n SELECT r.agent_run_id INTO bound_run_id FROM action_receipts r WHERE r.tenant_id=t AND r.id=own_receipts[1];\n SELECT * INTO ar FROM agent_runs a WHERE a.tenant_id=t AND a.category_id=c AND a.id=bound_run_id\n  AND a.requester_id=scope_requester();\n IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=t AND p.id=scope_actor() AND p.active AND p.kind='human') THEN RETURN true; END IF;\n IF EXISTS(SELECT 1 FROM action_receipts r WHERE r.tenant_id=t AND r.agent_run_id=bound_run_id AND NOT r.id=ANY(own_receipts)) THEN RETURN true; END IF;\n FOR rr IN SELECT r.* FROM action_receipts r WHERE r.id=ANY(own_receipts) LOOP\n  IF rr.tenant_id IS DISTINCT FROM t OR rr.category_id IS DISTINCT FROM c OR rr.agent_run_id IS DISTINCT FROM bound_run_id\n   OR rr.requester_id IS DISTINCT FROM ar.requester_id OR rr.run_id IS NOT NULL\n   OR (ar.product_id IS NOT NULL AND rr.product_id IS DISTINCT FROM ar.product_id)\n   OR NOT (rr.actor_id=ar.writer_id OR (rr.actor_id=ar.requester_id AND rr.operation='evidence.claim.record'\n    AND EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=t AND k.id=rr.subject_id AND k.run_id=bound_run_id\n     AND k.origin='ai_draft' AND k.writer_id=ar.writer_id AND k.confirmed_by=ar.requester_id AND k.receipt_id=rr.id)))\n   OR rr.operation NOT IN ('evidence.claim.record','evidence.artifact.register','evidence.link.create')\n   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(targets) x(v) WHERE v->>'type'=rr.subject_type AND (v->>'id')::uuid=rr.subject_id)\n   THEN RETURN true; END IF;\n END LOOP;\n IF (SELECT count(*) FROM action_receipts r WHERE r.id=ANY(own_receipts))<>cardinality(own_receipts) THEN RETURN true; END IF;\n FOR target IN SELECT v FROM jsonb_array_elements(targets) AS x(v) LOOP\n  IF target->>'type'='claim' THEN\n   IF NOT EXISTS (SELECT 1 FROM claims a WHERE a.tenant_id=t AND a.category_id=c AND a.id=(target->>'id')::uuid\n      AND a.human_owner_id=scope_requester() AND (a.run_id=bound_run_id OR a.receipt_id IS NULL) AND m3_claim_reader(t,c,a.id))\n    THEN RETURN true; END IF;\n  ELSIF target->>'type'='artifact' THEN\n   IF NOT EXISTS (SELECT 1 FROM artifact_versions a WHERE a.tenant_id=t AND a.category_id=c AND a.id=(target->>'id')::uuid\n      AND a.owner_id=scope_requester() AND direct_source_set_visible(t,c,a.product_id,jsonb_build_array(jsonb_build_object('artifact_id',a.id))))\n    THEN RETURN true; END IF;\n  ELSIF target->>'type'='evidence_link' THEN\n   IF NOT EXISTS(SELECT 1 FROM evidence_links l JOIN agent_runs a ON a.tenant_id=l.tenant_id AND a.id=l.run_id\n    WHERE l.tenant_id=t AND l.category_id=c AND l.id=(target->>'id')::uuid AND l.run_id=bound_run_id\n     AND l.origin='ai_draft' AND l.writer_id=a.writer_id AND a.requester_id=scope_requester()\n     AND m3_evidence_target_reader(t,c,l.target_type,l.target_id)) THEN RETURN true; END IF;\n  ELSE RETURN true; END IF;\n  ids=array_append(ids,(target->>'id')::uuid);\n END LOOP;\n FOREACH table_name IN ARRAY tables LOOP\n  FOR payload IN EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE tenant_id=$1 AND category_id=$2',table_name) USING t,c LOOP\n   IF (payload->>'id')::uuid=ANY(ids) OR (payload->>'id')::uuid=ANY(own_receipts)\n      OR (payload->>'receipt_id')::uuid=ANY(own_receipts) THEN CONTINUE; END IF;\n   IF table_name='evidence_links' AND payload->>'reverted_by_receipt_id' IS NOT NULL THEN CONTINUE; END IF;\n   IF table_name='proposal_item_versions' AND NOT EXISTS(SELECT 1 FROM proposal_items i WHERE i.tenant_id=t AND i.category_id=c\n    AND i.id=(payload->>'item_id')::uuid AND NOT i.removed AND i.current_version=(payload->>'version')::integer) THEN CONTINUE; END IF;\n   IF lifecycle_payload_links(payload) && ids OR m3_evidence_reference_ids(payload) && ids THEN RETURN true; END IF;\n  END LOOP;\n END LOOP;\n RETURN false;\nEND $function$\n"

REVERT_SUBJECTS_CONSUMED = "CREATE OR REPLACE FUNCTION public.revert_subjects_consumed(t uuid, c uuid, targets jsonb, own_receipts uuid[])\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE tables text[]=ARRAY['action_receipts','actual_configurations','artifact_versions','audit_entries','bom_lines','bom_revisions','build_authorization_decisions','build_current_authorizations','build_current_execution_assessments','build_execution_assessments','build_lots','build_operational_current','build_operational_facts','build_readiness','build_starts','builds','capa_current_observations','capa_current_verification_rules','capa_named_verification_reviews','capa_observation_facts','capa_remediation_links','capa_verification_evidence','capa_verification_rule_facts','change_approval_records','change_dependency_clocks','change_graph_captures','change_implementation_captures','change_implementation_records','change_order_records','change_request_currents','change_request_versions','claim_consumptions','claims','controlled_change_coverage_currents','controlled_change_coverage_facts','controlled_change_policy_currents','controlled_change_policy_facts','controlled_change_selection_currents','controlled_change_selection_facts','cost_current_inputs','cost_estimates','cost_input_snapshots','cost_source_captures','definition_revisions','definition_sources','definition_specs','engineering_configurations','manufacturing_baseline_document_links','manufacturing_preparation_currents','manufacturing_preparation_versions','measurement_import_captures','operational_material_holds','operational_resource_occupancies','original_scan_requests','original_scan_results','original_security','outbox_events','parts','plan_proposals','plan_revisions','process_revisions','product_variants','professional_authority_current','professional_authority_facts','project_product_links','project_tasks','project_work_packages','projects','quality_current_issues','quality_current_policies','quality_event_failure_links','quality_failure_maps','quality_issue_versions','quality_policy_facts','request_keys','runs','sample_allocations','sample_current_readiness','sample_readiness_facts','sample_run_usages','sample_units','sample_usage_sentinels','supply_current_snapshots','supply_kit_projections','supply_snapshots','supply_source_captures','task_dependencies','test_measurements','test_resource_current','test_resource_facts','test_resource_reservations','test_result_actions','test_result_projections','uploaded_originals','variant_revisions','verification_actual_method_applicabilities','verification_actual_method_batches','verification_current_actual_methods','verification_current_formal_requests','verification_current_preparations','verification_current_runs','verification_formal_requests','verification_handoff_facts','verification_launch_facts','verification_method_applicabilities','verification_preparations','verification_run_identities','verification_run_versions','verification_window_proposals','work_requests','proposals','proposal_item_versions','proposal_submissions','proposal_decisions','category_knowledge_entries','evidence_links']; table_name text; target jsonb; ids uuid[]='{}'; payload jsonb; bound_run_id uuid; rr action_receipts; ar agent_runs;\nBEGIN\n IF category_access(t,c,true) IS DISTINCT FROM true OR scope_actor() IS DISTINCT FROM scope_requester()\n  OR jsonb_typeof(targets) IS DISTINCT FROM 'array' OR own_receipts IS NULL THEN RETURN true; END IF;\n IF cardinality(own_receipts)=0 THEN RETURN jsonb_array_length(targets)<>0; END IF;\n IF cardinality(own_receipts)<>(SELECT count(DISTINCT v) FROM unnest(own_receipts) x(v))\n  OR jsonb_array_length(targets)<>(SELECT count(DISTINCT v->>'id') FROM jsonb_array_elements(targets) x(v)) THEN RETURN true; END IF;\n SELECT r.agent_run_id INTO bound_run_id FROM action_receipts r WHERE r.tenant_id=t AND r.id=own_receipts[1];\n SELECT * INTO ar FROM agent_runs a WHERE a.tenant_id=t AND a.category_id=c AND a.id=bound_run_id\n  AND a.requester_id=scope_requester();\n IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=t AND p.id=scope_actor() AND p.active AND p.kind='human') THEN RETURN true; END IF;\n IF EXISTS(SELECT 1 FROM action_receipts r WHERE r.tenant_id=t AND r.agent_run_id=bound_run_id AND NOT r.id=ANY(own_receipts)) THEN RETURN true; END IF;\n FOR rr IN SELECT r.* FROM action_receipts r WHERE r.id=ANY(own_receipts) LOOP\n  IF rr.tenant_id IS DISTINCT FROM t OR rr.category_id IS DISTINCT FROM c OR rr.agent_run_id IS DISTINCT FROM bound_run_id\n   OR rr.requester_id IS DISTINCT FROM ar.requester_id OR rr.run_id IS NOT NULL\n   OR (ar.product_id IS NOT NULL AND rr.product_id IS DISTINCT FROM ar.product_id)\n   OR NOT (rr.actor_id=ar.writer_id OR (rr.actor_id=ar.requester_id AND rr.operation='evidence.claim.record'\n    AND EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=t AND k.id=rr.subject_id AND k.run_id=bound_run_id\n     AND k.origin='ai_draft' AND k.writer_id=ar.writer_id AND k.confirmed_by=ar.requester_id AND k.receipt_id=rr.id))\n    OR (rr.actor_id=ar.requester_id AND rr.operation='product.definition.item.patch' AND EXISTS(SELECT 1 FROM definition_specs s\n      WHERE s.tenant_id=t AND s.receipt_id=rr.id AND s.run_id=ar.id AND s.origin='ai_draft'\n       AND s.writer_id=ar.writer_id AND s.confirmed_by=ar.requester_id)))\n   OR rr.operation NOT IN ('evidence.claim.record','evidence.artifact.register','evidence.link.create','product.definition.item.patch')\n   OR (rr.operation<>'product.definition.item.patch' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(targets) x(v) WHERE v->>'type'=rr.subject_type AND (v->>'id')::uuid=rr.subject_id))\n   OR (rr.operation='product.definition.item.patch' AND (NOT EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=t AND s.receipt_id=rr.id)\n    OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=t AND s.receipt_id=rr.id AND\n     (s.run_id IS DISTINCT FROM ar.id OR s.origin<>'ai_draft' OR s.writer_id IS DISTINCT FROM ar.writer_id\n      OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(targets) x(v) WHERE v->>'type'='definition_spec' AND v->>'id'=s.id::text)))))\n   THEN RETURN true; END IF;\n END LOOP;\n IF (SELECT count(*) FROM action_receipts r WHERE r.id=ANY(own_receipts))<>cardinality(own_receipts) THEN RETURN true; END IF;\n FOR target IN SELECT v FROM jsonb_array_elements(targets) AS x(v) LOOP\n  IF target->>'type'='claim' THEN\n   IF NOT EXISTS (SELECT 1 FROM claims a WHERE a.tenant_id=t AND a.category_id=c AND a.id=(target->>'id')::uuid\n      AND a.human_owner_id=scope_requester() AND (a.run_id=bound_run_id OR a.receipt_id IS NULL) AND m3_claim_reader(t,c,a.id))\n    THEN RETURN true; END IF;\n  ELSIF target->>'type'='artifact' THEN\n   IF NOT EXISTS (SELECT 1 FROM artifact_versions a WHERE a.tenant_id=t AND a.category_id=c AND a.id=(target->>'id')::uuid\n      AND a.owner_id=scope_requester() AND direct_source_set_visible(t,c,a.product_id,jsonb_build_array(jsonb_build_object('artifact_id',a.id))))\n    THEN RETURN true; END IF;\n  ELSIF target->>'type'='evidence_link' THEN\n   IF NOT EXISTS(SELECT 1 FROM evidence_links l JOIN agent_runs a ON a.tenant_id=l.tenant_id AND a.id=l.run_id\n    WHERE l.tenant_id=t AND l.category_id=c AND l.id=(target->>'id')::uuid AND l.run_id=bound_run_id\n     AND l.origin='ai_draft' AND l.writer_id=a.writer_id AND a.requester_id=scope_requester()\n     AND m3_evidence_target_reader(t,c,l.target_type,l.target_id)) THEN RETURN true; END IF;\n  ELSIF target->>'type'='definition_spec' THEN\n   IF NOT EXISTS(SELECT 1 FROM definition_specs s JOIN definition_revisions d ON d.tenant_id=s.tenant_id AND d.category_id=s.category_id AND d.id=s.definition_id\n    JOIN action_receipts r ON r.tenant_id=s.tenant_id AND r.id=s.receipt_id\n    WHERE s.tenant_id=t AND s.category_id=c AND s.id=(target->>'id')::uuid AND s.run_id=bound_run_id\n     AND s.origin='ai_draft' AND s.writer_id=ar.writer_id AND s.receipt_id=ANY(own_receipts)\n     AND r.operation='product.definition.item.patch' AND r.agent_run_id=bound_run_id\n     AND d.product_id=ar.product_id AND NOT d.sealed AND d.status='draft'\n     AND m3_evidence_target_reader(t,c,'definition_spec',s.id)\n     AND NOT m3_definition_fixed_consumed(t,c,d.id,d.revision)) THEN RETURN true; END IF;\n   -- Physical version history and current pointers do not consume their own\n   -- value. Actual fixed Definition consumers are checked above, atomically.\n   CONTINUE;\n  ELSE RETURN true; END IF;\n  IF NOT EXISTS(SELECT 1 FROM action_receipts r WHERE r.tenant_id=t AND r.id=ANY(own_receipts)\n    AND r.subject_type=target->>'type' AND r.subject_id=(target->>'id')::uuid) THEN RETURN true; END IF;\n  ids=array_append(ids,(target->>'id')::uuid);\n END LOOP;\n FOREACH table_name IN ARRAY tables LOOP\n  FOR payload IN EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE tenant_id=$1 AND category_id=$2',table_name) USING t,c LOOP\n   IF (payload->>'id')::uuid=ANY(ids) OR (payload->>'id')::uuid=ANY(own_receipts)\n      OR (payload->>'receipt_id')::uuid=ANY(own_receipts)\n      OR (payload->>'receipt_id')::uuid=ar.revert_receipt_id THEN CONTINUE; END IF;\n   IF table_name='evidence_links' AND payload->>'reverted_by_receipt_id' IS NOT NULL THEN CONTINUE; END IF;\n   IF table_name='proposal_item_versions' AND NOT EXISTS(SELECT 1 FROM proposal_items i WHERE i.tenant_id=t AND i.category_id=c\n    AND i.id=(payload->>'item_id')::uuid AND NOT i.removed AND i.current_version=(payload->>'version')::integer) THEN CONTINUE; END IF;\n   IF lifecycle_payload_links(payload) && ids OR m3_evidence_reference_ids(payload) && ids THEN RETURN true; END IF;\n  END LOOP;\n END LOOP;\n RETURN false;\nEND $function$\n"

RUN_REVERT_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_run_revert_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; original action_receipts; ids uuid[]; targets jsonb; expected_ids jsonb; rx xid;\nBEGIN\n IF NEW.revert_receipt_id IS NOT DISTINCT FROM OLD.revert_receipt_id THEN RETURN NULL; END IF;\n -- Existing S0-only run semantics remain with their original owner.\n IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.run_id=NEW.id)\n  AND NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.run_id=NEW.id AND k.receipt_id IS NOT NULL)\n  AND NOT EXISTS(SELECT 1 FROM action_receipts r WHERE r.tenant_id=NEW.tenant_id AND r.agent_run_id=NEW.id AND r.operation='product.definition.item.patch') THEN RETURN NULL; END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.revert_receipt_id;\n PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id;\n IF r.operation IS DISTINCT FROM 'ai.run.revert' OR r.subject_type IS DISTINCT FROM 'agent_run' OR r.subject_id IS DISTINCT FROM NEW.id\n  OR r.actor_id IS DISTINCT FROM scope_actor() OR r.requester_id IS DISTINCT FROM NEW.requester_id\n  OR r.actor_id IS DISTINCT FROM r.requester_id OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n  OR r.category_id IS DISTINCT FROM NEW.category_id OR r.product_id IS DISTINCT FROM NEW.product_id\n  OR rx IS DISTINCT FROM (SELECT xmin FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence run revert identity mismatch' USING ERRCODE='23514'; END IF;\n SELECT coalesce(array_agg(receipt.id ORDER BY receipt.id),'{}'::uuid[]),\n  coalesce(jsonb_agg(jsonb_build_object('type',receipt.subject_type,'id',receipt.subject_id) ORDER BY receipt.id),'[]'::jsonb),\n  coalesce(jsonb_agg(to_jsonb(receipt.id) ORDER BY receipt.id),'[]'::jsonb)\n INTO ids,targets,expected_ids FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id;\n SELECT coalesce(jsonb_agg(jsonb_build_object('type',typ,'id',id) ORDER BY id),'[]') INTO targets FROM (\n  SELECT receipt.subject_type typ,receipt.subject_id id FROM action_receipts receipt\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id AND receipt.operation<>'product.definition.item.patch'\n  UNION ALL SELECT 'definition_spec',spec.id FROM definition_specs spec JOIN action_receipts receipt\n   ON receipt.tenant_id=spec.tenant_id AND receipt.id=spec.receipt_id\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id AND receipt.operation='product.definition.item.patch'\n ) actual;\n IF EXISTS(SELECT 1 FROM action_receipts original WHERE original.tenant_id=NEW.tenant_id AND original.agent_run_id=NEW.id AND original.operation='product.definition.item.patch') THEN\n  IF jsonb_typeof(r.result->'definition_item_changes') IS DISTINCT FROM 'array'\n   OR jsonb_typeof(r.result->'retained_items') IS DISTINCT FROM 'array'\n   OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(r.result->'definition_item_changes'))\n    IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',s.item_id,'item_version',s.item_version,'row_id',s.id,'key',s.key,'removed',s.removed) ORDER BY s.id),'[]')\n     FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=r.id)\n   OR jsonb_array_length(r.result->'retained_items')<>(SELECT count(DISTINCT ROW(value->>'definition_id',value->>'item_id')) FROM jsonb_array_elements(r.result->'retained_items'))\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.result->'retained_items') retained WHERE\n    (retained-ARRAY['definition_id','item_id','reason'])<>'{}'::jsonb\n    OR retained->>'reason' IS DISTINCT FROM 'definition_item_changed_or_confirmed'\n    OR NOT EXISTS(SELECT 1 FROM definition_specs s JOIN action_receipts original ON original.tenant_id=s.tenant_id AND original.id=s.receipt_id\n     WHERE s.tenant_id=NEW.tenant_id AND s.definition_id::text=retained->>'definition_id' AND s.item_id::text=retained->>'item_id'\n      AND original.agent_run_id=NEW.id AND original.operation='product.definition.item.patch')\n    OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=r.id AND s.item_id::text=retained->>'item_id')) THEN\n   RAISE EXCEPTION 'definition revert changes or retained manifest mismatch' USING ERRCODE='23514'; END IF;\n END IF;\n IF jsonb_typeof(r.result->'receipt_ids') IS DISTINCT FROM 'array'\n  OR (SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) FROM jsonb_array_elements(r.result->'receipt_ids')) IS DISTINCT FROM expected_ids\n  OR revert_subjects_consumed(NEW.tenant_id,NEW.category_id,targets,ids) THEN\n  RAISE EXCEPTION 'evidence run revert incomplete or consumed' USING ERRCODE='23514'; END IF;\n FOR original IN SELECT receipt.* FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id LOOP\n  IF original.subject_type='claim' THEN\n   IF NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.id=original.subject_id\n    AND k.status='reverted' AND k.revision=original.subject_revision+1 AND k.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing claim' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='artifact' THEN\n   IF NOT EXISTS(SELECT 1 FROM artifact_versions a WHERE a.tenant_id=NEW.tenant_id AND a.id=original.subject_id\n    AND a.status='withdrawn' AND a.revision=original.subject_revision+1 AND a.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing artifact' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='evidence_link' THEN\n   IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.id=original.subject_id\n    AND l.reverted_by_receipt_id=r.id AND l.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing link' USING ERRCODE='23514'; END IF;\n  ELSIF original.operation='product.definition.item.patch' AND original.subject_type='definition_revision' THEN\n   IF NOT EXISTS(SELECT 1 FROM definition_specs spec WHERE spec.tenant_id=NEW.tenant_id AND spec.receipt_id=original.id)\n    OR EXISTS(SELECT 1 FROM definition_specs spec WHERE spec.tenant_id=NEW.tenant_id AND spec.receipt_id=original.id\n     AND NOT EXISTS(SELECT 1 FROM definition_specs compensation WHERE compensation.tenant_id=spec.tenant_id\n      AND compensation.item_id=spec.item_id AND compensation.receipt_id=r.id AND compensation.xmin=rx)\n     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(r.result->'retained_items','[]')) retained\n      JOIN definition_spec_current current ON current.tenant_id=spec.tenant_id AND current.item_id=spec.item_id\n      WHERE retained->>'definition_id'=spec.definition_id::text AND retained->>'item_id'=spec.item_id::text\n       AND retained->>'reason'='definition_item_changed_or_confirmed'\n       AND (current.current_row_id IS DISTINCT FROM (SELECT s.id FROM definition_specs s JOIN action_receipts original_receipt\n          ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id\n          WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id AND original_receipt.agent_run_id=NEW.id\n           AND original_receipt.operation='product.definition.item.patch' ORDER BY s.item_version DESC LIMIT 1)\n        OR EXISTS(SELECT 1 FROM definition_specs s JOIN action_receipts original_receipt ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id\n         WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id AND original_receipt.agent_run_id=NEW.id\n          AND original_receipt.operation='product.definition.item.patch' AND (s.confirmed_by IS NOT NULL OR s.item_status='confirmed'))\n        OR EXISTS(SELECT 1 FROM definition_specs gap WHERE gap.tenant_id=spec.tenant_id AND gap.item_id=spec.item_id\n          AND gap.item_version BETWEEN (SELECT min(s.item_version) FROM definition_specs s JOIN action_receipts original_receipt\n           ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id\n           AND original_receipt.agent_run_id=NEW.id AND original_receipt.operation='product.definition.item.patch') AND current.current_version\n          AND gap.run_id IS DISTINCT FROM NEW.id)))) THEN\n    RAISE EXCEPTION 'definition run revert requires actual compensation or protected retained item' USING ERRCODE='23514'; END IF;\n  ELSE RAISE EXCEPTION 'evidence run revert unsupported result' USING ERRCODE='23514'; END IF;\n END LOOP;\n RETURN NULL;\nEND $function$\n"

